window.CHAPTER_DATA["ch03"]={"id": "ch03", "num": 3, "part": "הקדמות וכללים - יום השבת - גדרי מלאכה - הוצאה - רשויות", "title": "גדרי מעשה", "paras": [{"s": "h2", "h": "\u003csup class=\"cb\" data-c=\"841\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">1\u003c/sup>\u003cspan class=\"ca\" data-c=\"841\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">גדרי מעשה\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"55\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">2\u003c/sup>\u003cspan class=\"ca\" data-c=\"55\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">מלאכת הוצאה נאסרה לנו בכלל איסורי מלאכות, ובכלל מעשי איסור, וכיון שהיא מורכבת משלושה מושגים שהם המעשה, המלאכה ומושגי הוצאה, נדרשים אנו לבאר ביתר ביאור שלושה חלקים אלו.\u003c/span>"}, {"s": "p", "h": "ונחל במעשה שהוא ביחס כללי לכל מעשים שבעולם המותרים, המחוייבים והאסורים. "}, {"s": "p", "h": "והנה נדרשים אנו להקדים אי אלו דברים הנוגעים לגדרי מעשה באופן כללי שהם כהקדמה למעשה של מלאכה בשבת."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"56\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">3\u003c/sup>\u003cspan class=\"ca\" data-c=\"56\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">המעשה כולל שלושה מרכיבים העושה התוצאה ואת התעסקות העושה בתוצאה, והתוצאה כשמה כן היא המציאות הנובעת מן המעשה\u003c/span>"}, {"s": "h3", "h": "מציאות המעשה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"57\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">4\u003c/sup>\u003cspan class=\"ca\" data-c=\"57\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">מציאות המעשה, היינו, המציאות לפני המעשה, המציאות בשעת המעשה והמציאות שנמצאה בעקבות עשיית המעשה, כי המושג מעשה כדבר שהתחדש הוא המציאות בעלת המשמעות, ומושג זה מחייב מציאות של דברים קיימים, ומשמעות במציאות אותם הדברים, ומשמעות ביחס שביניהם.\u003c/span>"}, {"s": "p", "h": "ולקרב הדברים נבאר את הגדרים ביחס למעשה מסוים של אוכל המונח במקום חשוב ברשות הרבים. המעשה במובן הזה הוא מעשה של הרשות שמכילה את האוכל."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"58\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">5\u003c/sup>\u003cspan class=\"ca\" data-c=\"58\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ונחלק את הדברים שהמושגים חפץ כדבר, היינו, חומר תופס מקום ומקום כדבר, היינו, חלל המכיל דברים והיות החפץ נח במקום לאורך זמן הם מושגים מציאותיים ונוכל לדון בהם כך, אך המושגים אוכל, מקום חשוב, רשות ורשות הרבים, הינם מושגים שימושיים ונצטרך לדון בהם במובנם השימושי, ונדון תחילה במושגים המציאותיים.\u003c/span>"}, {"s": "h4", "h": "\u003csup class=\"cb\" data-c=\"842\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">6\u003c/sup>\u003cspan class=\"ca\" data-c=\"842\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">מושגי המציאות\u003c/span>"}, {"s": "p", "h": "ונבהיר כל שם מהדברים שנדבר ליתר ביאור בצורת השימוש בהם."}, {"s": "h7", "h": "מושג"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"59\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">7\u003c/sup>\u003cspan class=\"ca\" data-c=\"59\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">מושג, שם מושג הוא מה שנתפס כדבר מוגדר ביחס לדבר אחר ודורש השגה ואינו מצוי, והמושג לבד, היינו, מה ששייך שיתפוס השכל כדבר מוגדר ושלא יהיה נסתר מעצמו, וביחס לבחינת מציאות כשנגדיר דבר שאינו קיים במציאות אך יתכן שיתקיים הוא יחשב כמושג מציאותי, וכן כשנרצה להגדיר חלק ממקרה מציאותי בנפרד משאר המציאות אף אם הוא לא קיים במציאות בנפרד גם הוא יחשב מושג מציאותי. ובדוגמא שלנו שחפץ מונח במקום, החפץ הוא מושג, מציאותי, נפרד, ובעל צורה. וכן המקום. וכן מושג המקרה שחפץ מונח במקום הוא מושג, מציאותי, נפרד ממקרה אחר, ובעל צורה אחידה של החפץ והמקום.\u003c/span>"}, {"s": "h7", "h": "קיים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"60\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">8\u003c/sup>\u003cspan class=\"ca\" data-c=\"60\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">קיום, שם קם הוא מה שכבר עומד ולא רק אפשרי, וביחס להשגת השכל הוא בחינה של דבר אם קיים כמושג הגיוני לעצמו, וביחס למציאות הוא בחינה של דבר אם קיים במציאות או לא, ובחינת זו היא בחינה מוחלטת שהקיום היא חיובית ואי הקיום היא שלילית, והגדרת הקיים ושאינו קיים במציאות ביחס להיותו מושג היא מאוחרת להגדרת הדברים עצמם שאותם נגדיר כקיימים כמושג או לאו. ובדוגמא שלנו החפץ קיים כמושג, ובמציאות, וכן המקום, והמקרה שחפץ מונח במקום אף הוא קיים כמושג, וכמציאות. \u003c/span>"}, {"s": "h7", "h": "דבר"}, {"s": "p", "h": "דבר, שם דבר הוא מה שניתן לדבר עליו, היינו, שיהיה מובחן משאר דברים. ואם נדבר על דבר מציאותי הוא ביחס למציאות, ואם נדבר על דבר כמושג מציאותי הוא יהיה ביחס להשגתו, ובחינת מה כדבר הוא לפחות כמושג, אך מה שלא ניתן לדבר עליו כמושג אינו נחשב דבר כלל, וזה יהיה קודם לבחינת הקיום שמה שאינו דבר ודאי אינו שייך בקיום כדבר, אך הדבר שייך לבוחנו בבחינת הקיום אם קיים הוא או לא. ובדוגמא שלנו החפץ הוא דבר והמקום הוא דבר, וכן המקרה המאוחד ביחס לדבר אחר."}, {"s": "h5", "h": "המציאות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"61\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">9\u003c/sup>\u003cspan class=\"ca\" data-c=\"61\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">המציאות היא כל הדברים המצויים, והדבר הקיים יוגדר ביחס למציאות כנמצא, ובמציאות ככלל לא יהיה שום משמעות חוץ לעצם הקיום, שלא יהיה משמעות לדבר הקיים, אלא עצם זה שיש הבדל במציאות שאם הדבר קיים אז הוא נמצא והלא קיים אינו נמצא. והמציאות היא העצם וקיום הדבר הוא מקרה בה, והמציאות בהיותה כוללת כל הדברים תגדיר יחס בין הדברים הקיימים אם שייך שיתקיימו יחדיו, ומשמעות קיומם ביחס לאחר.\u003c/span>"}, {"s": "h7", "h": "מושג הדבר הקיים הנפרד"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"62\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">10\u003c/sup>\u003cspan class=\"ca\" data-c=\"62\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">שאף שאמרנו שהמציאות תכיל כל הדברים נוכל לדבר על דבר שקיים כחלק מהמציאות כמושג מציאותי נפרד. ובבחינה זו אנו נותנים משמעות קיום עצמית לדבר מסוים שיהיה שייך בו הגדרות הקיום בנפרד דהיינו קיומו ללא שיהיה תלוי בקיום דבר אחר, ושיהיה הדבר העצם ושאר המציאות כמקרה בעצם. ובדוגמא שאמרנו חפץ יוגדר כקיום נפרד והמקום יוגדר כקיום נפרד. אך לא יהיה שום משמעות בחפץ או במקום כי אין להם משמעות שונה של קיום עצמי ביחס לכל שני דברים אחרים.\u003c/span>"}, {"s": "h7", "h": "מציאות דברים נפרדים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"63\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">11\u003c/sup>\u003cspan class=\"ca\" data-c=\"63\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">כמו שאמרנו המציאות הכוללת את כל הדברים הקיימים תהיה בעלת משמעות אחידה מבחינת קיום דברים, והיינו, שלגבי מה שהדברים קיימים אין במציאות משמעות מחולקת, וכל המציאות היא דבר אחד של קיום, וכל הדברים הקיימים בה יהיו מציאות אחת. אך אחר שנגדיר חלק מהמציאות כקיום של דבר נפרד תיפרד המציאות ביחס לדבר הנפרד הנמצא בה וקיומו יהיה חלק מציאות נפרד. והגדרת המציאות האחת ביחס לדברים הנפרדים תהיה מציאות כוללת שאמנם היא אחת ביחס למושג הקיום של הדברים, אך לא ביחס לנפרדותם, ועל כן תוגדר ככוללת. שהיא מציאות אחת של המושג קיום המכילה קיימים נפרדים רבים, דהיינו שמציאות הנחלקת משום היות הדברים הקיימים נפרדים לא יהיו חלקיה נפרדים כי משמעות הקיום של כל הדברים היא אחת או שהם קיימים או שלא וחלקי המציאות יהיו רק במובן של קיום שונה והוא משם שני וזה המופרדות היותר חלשה ובמובן של דבר נספר. ובדוגמא שאמרנו החפץ והמקום יוגדרו כמציאות אחת של שני קיימים נפרדים, ויהיה משמעות ששניהם כלולים במציאות אחת, ושאין קיום אחד סותר את קיום האחר, אך אין משמעות לחפץ כחומר ולמקום כחלל כי אין להם משמעות רק מה שהינם שני דברים קיימים במציאות אחת, וזה משמעות כל שני דברים.\u003c/span>"}, {"s": "h7", "h": "מושג דבר בעל צורה"}, {"s": "p", "h": "היינו מה שדבר הוא בעל צורה, וביחס לקיומו הוא מציאות אחת עם כל שאר דברים כאמור, וביחס לנפרדותו הוא קיים בנפרד משאר דברים, אך ביחס לצורה הוא מושג מציאותי נוסף, וביחס לקיומו יש משמעות שהוא נמצא בגבול, וביחס לנפרדותו יש משמעות שהוא נפרד מסיבת צורתו, והוא משמעות קיום נוספת ועל כן לא יפרד מצורה השווה לו. ובדוגמא שאמרנו החפץ והמקום הם בעלי צורה שונה, שהחפץ הוא צורה של חומר, ומקום הוא צורה של חלל, אך אין במה שהחפץ מונח במקום הזה משמעות שונה בחפץ או במקום ביחס לקיומם כצורה שצורתם אינה תלויה בזה. וביחס לקיומם הם יהיו קיימים בצורתם, וביחס לנפרדותם יהיה להם משמעות עצמית שהם נפרדים ע\"י צורתם, אך לא יהיה גדר חפץ שאין משמעות אחידה לחפץ כולו כנפרד שהרי ביחס לצורתו כחומר אין הוא דבר אחד לעצמו, כי אין הבדל בינו לשאר חפצים במשמעות צורתו החומרית. וכן לא יהיה משמעות אחידה למקום זה שביחס לצורתו כחלל אין הוא דבר לעצמו כי אין הבדל בינו לבין שאר חללים ביחס להיותו בעל צורת חלל."}, {"s": "h7", "h": "מציאות דברים בעלי צורה"}, {"s": "p", "h": "המציאות הכוללת את כל הצורות תכלול דברים בעלי צורות שונות למציאות אחד, והם יחשבו ביחס למציאות כקיימים ויחשב כל בעל צורה כקיים, וביחס למציאות הכוללת, הם יתחלקו לסוגים, שבעלי צורה יש להם גבול וביחס לדברים אחרים גבול דבר זה הוא סייגו של האחר, ויוגדרו ביחס להתאמתם הצורתית, שיש שצורתם תאפשר שיתקיימו בחלק מציאות אחד והמציאות הכוללת תהיה מתאימה לקיום הצורות, ומציאות שני צורות תגדיר אותם כמתאימות. ובדוגמא שאמרנו. החפץ והמקום ביחס למציאות, למציאות חפץ המונח במקום בבחינת המקום והחפץ לעצמם יש משמעות כמתאימה שצורות של חומר וחלל יכולים להתקיים במציאות אחת, וביחס להיותם נפרדים יהיה דבר בחלל יחד משמעות כדבר נפרד ביחס לשאר מקרי דבר בחלל, אך לא יהיה הבדל ביחס לשאר מקרים של דבר הנמצא במקום, ולא יהיה משמעות לדבר כחפץ אלא כחומר רב וכן למקום רק כחלל אך לא במה שהוא מונח במקום או ביחס לחפץ זה ומקום זה כי אין בזה משמעות ביחס למציאות הצורות."}, {"s": "h7", "h": "מושג הדבר הנפרד בעל הצורה הנבדלת"}, {"s": "p", "h": "דבר בעל צורה הרי שהוא נפרד מלבד בקיומו הרי שהוא נפרד גם בצורתו וביחס למציאות יוגדר זה כמושג מציאותי עצמי, שכיון שיש צורות המתאימות ויש שאינם הרי שנוכל להגדיר את צורת הדבר ביחס לצורות אחרות כהגדרה עצמית, ויהיה הדבר נפרד לא רק בקיומו שהוא קיים מסיבת עצמו אלא גם מסיבת צורתו, ומושג זה יהיה כולל הגדרות רבות בדבר קיים, נפרד, ובעל צורה. ובדוגמא שלנו שחפץ מונח במקום, ביחס לקיומו, להתאמת הצורות הנבדלות, היינו, דבר בחלל יהיה משמעות לדבר שהחלל מכיל אותו כמעשה שעושה החלל בדבר שהרי ביחס למציאות הצורות אין מציאות של דבר שאינו נמצא בחלל, וזה יהיה חלק מהגדרת דבר כקיים במציאות הצורות ונגדיר את החלל שבו הוא נמצא כמקיימו, אך לא יהיה בזה משמעות קיומית לחלל המכיל דבר שהרי אין הדבר מקיים את החלל שבמציאות שייך שיהיה חלל ריק ואם כן מה שחלל מכיל דבר לא יהיה חלק מהגדרתו כקיים במציאות. וביחס לנפרדותם יהיה משמעות בחלל בעל הצורה המכיל דבר כדבר בעל קיום נפרד שהרי ביחס למה שהוא מכיל דבר הרי אינו יכול להכיל עוד דבר וא\"כ חלל המכיל דבר יחשבו לדבר נפרד ביחס לחללים אחרים שאינם מכילים דבר, היינו, ריק ומלא, וכיון שהדבר הנמצא בתוכם מוגדר כדבר קיים בחלל יהיה להם משמעות מקום, וכיון שהוא קיים כדבר נפרד יהיה משמעות בכל חלל המכיל דבר נפרד כמקום נפרד. "}, {"s": "h7", "h": "מציאות של דברים נבדלים"}, {"s": "p", "h": "היא המציאות הכוללת כל הדברים הנבדלים והיא תגדיר משמעויות כלליות בדברים הנבדלים, ותגדיר בדבר את יחסיו עם הדבר הנבדל האחר, ובדוגמא שלנו החפץ שהוא דבר בעל צורת חומר ביחס למציאות הכללית יהיה משמעות שהוא נמצא בתוך החלל שכיון שהחלל הכללי הוא אחיד בצורתו והוא נמצא בחלקו יוגדר שהוא נמצא בתוכו, אך לחפץ כולו כאחד לא יהיה משמעות כדבר נפרד משאר דברים, ואף ביחס למקום שהרי כל הדברים נמצאים במקום. וביחס למציאות הכללית של דברים נבדלים יהיה לכל הצורות השונות משמעות אחת כנבדלים. ויהיה משמעות קיום לדבר בעל הצורה המסוימת כמובדל משאר דברים בעלי צורה, וכיון שיש צורות שונות לחומר ולחלל יהיה משמעות אחידה של קיום לכל חומר החפץ כדבר אחד, וכן יהיה משמעות אחידה לחלל הנבדל בצורתו וביחס לחפץ בתוך מקום החפץ כולו יוגדר כדבר אחד ביחס לשאר חפצים אך לא יהיה למקום החפץ משמעות אחידה שאינו בעל צורה נבדלת משאר חללים וכן יהיה לדברים בעלי צורה משמעות נפרדת שהרי ביחס למקום זה לא כל הדברים בעלי הצורה יתקיימו במקום זה שהרי צורתם נבדלת בגודלם וכו' אך ביחס לחלל בעל הצורה לא יהיה משמעות לחלל כדבר בעל צורה נפרד שהרי מכיל את כל הדברים בעלי הצורה באחת. וכן לא יהיה משמעות למה שהחפץ מונח במקום. "}, {"s": "h5", "h": "סיכום"}, {"s": "p", "h": "כל המשמעויות שיש לדברים שכתבנו עד עתה הם משמעויות גשמיות שדבר קיים או נפרד או שהוא צורה הם נושאים גשמיים הנמצאים בדברים."}, {"s": "p", "h": "וקיום דבר אחד אין הוא נושא אחד עם קיום דבר שני, ונפרדות דבר נוגעת למה שהוא פרט מהכלל, וצורות הוא נושא המבדיל בין שני דברים."}, {"s": "p", "h": "ותהיה בזה בחינה משולשת ביחס לדבר והוא האם דבר מושג, האם דבר קיים, האם דבר מושג כנפרד, האם דבר קיים כנפרד, האם דבר מושג כצורה, האם דבר קיים כצורה, האם דבר מושג כנפרד בצורתו האם דבר קיים כנפרד בצורתו, האם הדבר מושג כנבדל בצורתו, והאם הדבר קיים כנבדל בצורתו. ובדוגמא שלנו שהחפץ והמקום הרי הם מושגים מציאותיים החפץ כדבר והמקום כדבר והם קיימים במציאות וכן הם מושגים נפרדים החפץ כדבר אחד והמקום כדבר אחד וקיימים במציאות כשני דברים שונים. וכן הם מושגים בעלי צורה החפץ הוא בעל צורה והמקום הוא בעל צורה וקיימים בצורתם החפץ קיים, ונבדלים בצורתם החפץ הוא חומר והמקום הוא חלל והם קיימים במציאות כשני צורות נבדלות."}, {"s": "h4", "h": "מושגי המציאות כמשמשת לאדם"}, {"s": "h7", "h": "האדם"}, {"s": "p", "h": "כיון שהמציאות משמשת את האדם וכל משמעותה השימושית היא רק ביחס לאדם שהוא תכלית הנברא, וכל אשר יקרא להם הם שמם. מושגים שימושיים של האדם יוגדרו כמושגים מציאותיים ביחס לאדם, ויהיה להם את אותם הגדרים המציאותיים כמו במשמעויות הגשמיות."}, {"s": "p", "h": "ויהיו בזה חילוקים כמו במשמעות המציאותית, מושגים שימושיים הנוגעים להיותו בר שימוש באופן כללי יגדירו את קיום הדבר ביחס לשימוש ודבר שאינו בר שימוש יחשב ביחס לזה כלא קיים מבחינה שימושית, ומושגים הנוגעים לשימוש הדבר כמשמש לסוג שימוש יגדירו את הדבר כנפרד משאר דברים שימושיים, ומושגים הנוגעים להתאמתו השימושית יגדירו דבר כבעל צורה שימושי, אמנם אף שגדרי הדבר ביחס לשימוש נוגעים למושגים שימושיים אין זה מבטל את משמעות המושגים גשמיים של דבר שפשוט שדבר שאינו קיים במושג המציאות לא יהיה מושג שימושי, אך יתכן שדבר שלא קיים במציאות אבל קיים כמושג מציאותי יהיה שייך שיהיה גם מושג כשימושי וכן לגבי שאר עניינים."}, {"s": "h7", "h": "הזמן"}, {"s": "p", "h": "כיון שנושא השימוש הוא ביחס לאדם, הזמן יהיה חלק ממשמעותו השימושית של דבר, ויהיה הזמן בחינה לשלושת המושגים השימושיים שבכדי שיחשב בר שימוש יש לו להיות בר שימוש במשך זמן השימוש, וכן ביחס לסוג השימוש שיש שימושים ארוכי זמן ויש קצרים וכן ביחס להתאמתו שיהיה מאפשר זמן שימוש. "}, {"s": "h7", "h": "מושג דבר בר שימוש"}, {"s": "p", "h": "מציאות דבר במשמעותו כדבר שיכול לשמש אדם, ומשמעות זו תושג רק על דבר שקיים כמושג מציאותי נפרד ובעל צורה, ובחינת המציאות הנ\"ל תגדיר האם הוא קיים כבר שימוש, ובדוגמא שלנו שחפץ מונח במקום, החפץ מוגדר כדבר בר שימוש קיים כיון שאפשר להשתמש בו וביחס לשימושו יחשב כחפץ כיון שהוא בר שימוש שיחפצים בו, וכן המקום יוגדר כדבר בר שימוש שכן הוא מאפשר קיום דברים וביחס לשימושו יחשב כרשות כיון שהוא מקום בר שימוש."}, {"s": "h7", "h": "מציאות דברים ברי שימוש"}, {"s": "p", "h": "המציאות הכוללת של דברים ברי שימוש תגדיר את הדברים בקיימים במציאות אחת ונפרדים בקיומם, והיא תהיה מציאות כוללת שביחס לקיומם כברי שימוש תהיה המציאות אחידה, אך ביחס דברים ברי שימוש קיימים יחשבו כדברים נפרדים. ובדוגמא שלנו שחפץ מונח במקום, החפץ ביחס לשימושו יוגדר כדבר בר שימוש וביחס להיותו במקום יחשב כמשתמש במקום והמקום יוגדר כדבר בר שימוש נפרד וביחס להיות בו חפץ יחשב כמשמש לחפץ."}, {"s": "h7", "h": "מושג דבר המשמש לשימוש נפרד"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"64\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">12\u003c/sup>\u003cspan class=\"ca\" data-c=\"64\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">מציאות דבר המשמש לשימוש נפרד יגדירו את הדבר כנפרד ביחס לקיום כלל דברים ברי שימוש, ומציאות זו תושג רק על דבר בר שימוש, ובחינת המציאות תגדיר האם הוא קיים כמשמש שימוש נפרד משאר דברים המשמשים, ובדוגמא שלנו החפץ יוגדר כמשמש שימוש נפרד כמטלטל והמקום יוגדר כמשמש שימוש נפרד כקרקע והחפץ המיטלטל ביחס להיותו במקום יוגדר כתופס מקום, והמקום ביחס להיות בו חפץ יוגדר כתופס את החפץ, ויצאו מכלל זה אוויר שאינו מקום בר שימוש כשימוש נפרד ודבר הגדול מבית סאתיים שאינו חפץ בר שימוש כשימוש נפרד.\u003c/span>"}, {"s": "h7", "h": "מציאות של דברים בעלי שימוש נפרד"}, {"s": "p", "h": "המציאות הנ\"ל תגדיר את הדברים כקיימים במציאות אחת ותגדיר יחסים בין דברים בעלי שימושים, שכל הדברים המשמשים יחשבו כמציאות שימושית אחת, אך יחלקו לסוגי שימושים שונים, ובדוגמא שלנו שחפץ מונח במקום החפץ ביחס להיותו בר שימוש יוגדר כבעל מקום ויש בזה משמעות שהוא מוכן לשימוש וביחס להיותו נפרד יהיה לכלל החפץ משמעות שימושית אחת וביחס למקום יחשב שכל החפץ כנמצא במקום אחד והמקום ביחס להיותו בר שימוש יוגדר כמקום שימוש של החפץ ושהוא נמצא בתוכו וביחס להיותו נפרד יהיה לכל המקום שם משמעות שימושית אחת כרשות של החפץ."}, {"s": "h7", "h": "מושג דבר בעל צורה שימושית"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"65\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">13\u003c/sup>\u003cspan class=\"ca\" data-c=\"65\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">מציאות דבר שצורתו משמשת לשימוש יגדיר את הדבר כמוכן ביחס לשימושים נפרד, ויהיה עליו שם השימוש, ובדוגמא שלנו שחפץ מונח במקום, החפץ בעל הצורה ביחס להיותו בר שימוש יוגדר ככלי שהוא שם חפץ המוכן לשימוש מסוים, וביחס להיותו בר שימוש נפרד יוגדר כאוכל, והמקום ביחס להיות בר שימוש יוגדר כולו כרשות אחת שהיא שם מקום המיועד לשימוש מסויים, וביחס להיותו בר שימוש נפרד יוגדר אם לשימוש היחיד ואם לשימוש הרבים.\u003c/span>"}, {"s": "h7", "h": "מציאות של דברים בעלי צורה שימושית"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"66\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">14\u003c/sup>\u003cspan class=\"ca\" data-c=\"66\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">המציאות הכוללת את כל הדברים בעלי צורה שימושית, ובדוגמא שלנו שחפץ מונח במקום, החפץ ביחס למקום יוגדר כנמצא ברשות, והיינו, שמלבד מה שממוקם במקום שיש עליו שם הרשות כשינוח ברשות יוגדר כך ביחס לכלל הרשות ואם יש לרשות משמעות תוך יחשב כנמצא בתוכה והמקום ביחס לחפץ יוגדר שהוא כרשות אחת מכיל את כל הדברים הנמצאים בכלל מקומותיו, וביחס לקיומם כדבר בר שימוש החפץ בעל צורת אוכל מוגדר כקיים מבחינה שימושית אם הוא בר אכילה וכן המקום בעל צורת רשות מוגדר כקיים מבחינה שימושית אם הוא בר שימוש כמקום אחיד וביחס לקיומם במציאות הכללית החפץ בהיותו בעל צורה שימושית להיחשב כנפרד צריך שיהיה בו שיעור ביחס לשימושו והוא שיעור גרוגרת והמקום בהיותו בעל צורה שימושית להיחשב כנפרד צריך שיהיה בו שיעור ביחס להיות מקום והוא שיעור ד' וביחס למציאות המותאמת החפץ בהיותו בעל צורה שימושית נפרדת בכדי להיות מתאים להיחשב כולו בתוך כלל הרשות צריך שינוח במקום חשוב והמקום בכדי להיחשב כרשות הרבים או היחיד צריך שיהיה בו שיעורי רשות הרבים טז' אמה וכו' או רשות היחיד וכו'.\u003c/span>"}, {"s": "p", "h": "משמעות קניין ביחס לשימוש וגדר דבר כמשמש - שימוש מוכן הנוגד תפיסת אחרים מול ערך מסחרי "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"67\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">15\u003c/sup>\u003cspan class=\"ca\" data-c=\"67\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ולתוספת ביאור גדר שימוש הנ\"ל בדבר, הנה גדר הנ\"ל הוא גם עיקר משמעות קניין חפץ (והוא גם פשר שייכות קניין חפץ לדיני רשויות), וכי יש משמעות לאדם בחפץ שיש לו בו קניין מהפקר לגבי שימוש, ומשמעות זו תבוא בשני פנים, האחד השימוש המוכן, שגדרו לא בעצם הקניין שלו, אלא במה שהוא נוגד תפיסת שימוש דאחרים. והשני הוא ערכו המסחרי, שאמנם אף הוא מעלת שימוש עקיפה, וגדרו במה שהוא שלו, שאין גדר שימוש זה במה שהוא אינו שימוש לאחרים, ואדרבה ככל שיהיה לאחרים בו משמעות שימוש יגדל ערכו המסחרי, וזה עיקר משמעות קיום חילוק קניין בגוף ופירות. וע\"כ לא שייך שיתוף גמור לגבי קניין הגוף (דאף בשותפים שלא יהיה להם חילוק גוף לגבי קנין, כמו מי שקנו יחד דבר, זה מחמת שיש להם משמעות משותפת בערכו המסחרי ביחס לכלל העולם. אך כשלא יהיה להם משמעות משותפת, יתעורר קנין הגוף להתחלק. ואכ\"מ). אך לגבי פירות, היינו, גדר מה ששימוש דבר זה מוכן, כיון שגדר שלו הוא רק מה שנוגד תפיסת שימוש דאחרים, באם יהיה הדבר ראוי לשימוש כמה אנשים יהיה שייך שיתוף גמור, ביחס לזה שאין חסרון בגדר מה שדבר זה שלו ע\"י שיתוף זה. \u003c/span>"}, {"s": "p", "h": "ויש בזה עוד חלוקה הנצרכת לעניננו לגבי גדר השימוש, דמה שדבר קנוי נחשב מוכן לשימוש הוא ביחס לשימוש מסויים, היינו, שכשיתעורר צורך מסויים, הרי שדבר קנוי מוכן לו יותר משאינו קנוי. אך גדר השימוש לגבי ערכו המסחרי הוא לא בנוגע לשימוש מסויים, אלא לכלל השימושים האפשריים כאחד. וע\"כ בגדר הראשון יהיה משמעות למה הוא משמש יותר מגדר למי הוא משמש, שגדר הדבר עצמו הוא השימוש, והיותו שלו הוא ערך בזה. אך לגבי ערכו המסחרי כיון שאין זה ביחס לצורך של שימוש מסויים, יהיה גדר הדבר עצמו במה שהוא שלו, והיותו משמש הוא תוספת ערך בזה. ודי בזה."}, {"s": "p", "h": "ותהיה השתלשלות משמעות דקנין לגבי שימוש הוא כך. דבר המוכן לשימוש מסויים, וגדר הקניין הוא במה שאין לאחרים יכולת תפיסת שימוש בו. דבר הראוי לשימוש סתם ולכל העולם, וגדר הקניין הוא במה שהוא שלו לסחור בו. "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"68\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">16\u003c/sup>\u003cspan class=\"ca\" data-c=\"68\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">(ועל כן מי שנתן רשות קבועה לאחר להשתמש בשלו, הרי ששיתפו בקניין הדבר כמוכן לשימוש, וכיון שאף לבעלים עצמו אין גדר קנין זה מה שהוא שלו, אלא מה שאין לאחרים תפיסה בו, אין הבדל בינו לבין הבעלים לגבי גדר זה, אלא כיון שאין גדר זה עומד לעצמו, שלא השכיר לו המקום לומר שמכר גדר זה, אלא הוא חלק מקניינו הכולל של הבעלים, לא יכול מקבל הרשות להשכירו, והוא פשר הדין דלא מהני מה שיש לבני החצר רשות וקניין להשתמש בחצר גבי שכירות מגוי, ואף ששימושם הוא משום שיעבוד שיש להם על הגוי לא מהני, דאין לזה שייכות עם מה שיש לגוי זכות להשתמש בחצר, ומה שיש לו קניין בכל החצר שלא ימנעו ממנו להשתמש, שזה קנין שלו, וכמו גדר קניין בערכו המסחרי, ואין שותפותם בקניין השימושי מועיל לעניין זה. והוא ביאור דין שכירו לגבי ביתו.)\u003c/span>"}, {"s": "h4", "h": "סיכום"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"69\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">17\u003c/sup>\u003cspan class=\"ca\" data-c=\"69\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ואם נסכם את כלל הדברים ביחס למעשה זה, הרי שמצאנו בחפץ כמה גדרים מן הפשוט למרוכב, דבר, קיים, נפרד, בעל צורה, בר שימוש, בר שימוש נפרד ובעל צורה שימושית. כדבר קיים נפרד ובעל צורה, יוגדר כדבר תופס ומתקיים ע\"י מקום, כבר שימוש יוגדר כחפץ, כבר שימוש נפרד יוגדר כל החפץ כדבר אחד. וכבעל צורה שימושית, יוגדר קיים כאוכל, ונפרד כאוכל חשוב, ומתאים כנמצא בתוך הרשות. וכן ביחס למקום, כדבר נפרד ובעל צורה יוגדר כמקום, כבר שימוש יוגדר כרשות, כבר שימוש נפרד יוגדר כרשות חפץ. כבעל צורה שימושית, יוגדר קיים כרשות, נפרד כמקום חשוב, ומתאים כרשות הרבים. וכן ביחס למעשה של חפץ במקום כדברים קיימים נפרדים ובעלי צורה, יחשבו כדבר במקום. כברי שימוש, יחשבו כחפץ ברשות. כברי שימוש נפרד, ככלי ברשותו. כבעלי צורה שימושית, יחשבו קיימים, כאוכל במקום רשות. נפרדים, כאוכל חשוב במקום חשוב. ומתאימים, כאוכל בתוך רשות הרבים.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"844\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">20\u003c/sup>\u003csup class=\"cb\" data-c=\"843\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">19\u003c/sup>\u003csup class=\"cb\" data-c=\"70\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">18\u003c/sup>\u003cspan class=\"ca\" data-c=\"70 843 844\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ואם נגדיר את משמעות חפץ במקום נגדיר בזה כמה משמעויות. מבחינת החפץ, מה שהוא צורת חומר, שהוא צורת דבר שאינו סותר קיום אחד עם חלל, ומה שהוא צריך חלל, ומה שהוא נחשב מקוים ע\"י חללו, ומה שהוא תופס חלל. ומה שהוא חומר בר שימוש, שאינו סותר שימוש אחד עם שימוש במקום, ומה שהוא צריך מקום, ומה שהוא מוכן לשימוש ע\"י מקום, ומה שהוא תופס מקום שימוש כרשותו. ומה שהוא בר שימוש ברשות, שאינו סותר שימוש אחד עם שימוש ברשות, ומה שהוא צריך רשות, ומה שהוא נחשב מורשה לשימוש ע\"י רשות, ומה שהוא תופס רשות שימוש כשלו. ומבחינת המקום, מה שהוא צורת חלל, שאינו סותר קיום אחד עם חומר, ומה שהוא מכיל חומר, ומה שהוא מקיים חומר, ומה שהוא מלא מחומר. ומה שהוא חלל בר שימוש, שאינו סותר שימוש אחד עם שימוש בחפץ, ומה שהוא מכיל חפץ, ומה שהוא מכין חפץ לשימוש, ומה שהוא משומש ע\"י חפץ. ומה שהוא רשות ברת שימוש, שאינו סותר שימוש אחד עם השתמשות חפץ בחלק ממקומו, ומה שמגדיר את מקומו כמשמש לרשותו, ומה שהוא מוגדר ע\"י מקומו.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"71\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">21\u003c/sup>\u003cspan class=\"ca\" data-c=\"71\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וענין המציאות האמורה היא בחינה של הדברים ומצבם בנמצא ואין בה הגדרה של שינוי שהוא הגדרה המתייחסת למה שהיה נמצא ומה שנמצא עכשיו, וכן לעתיד שימצא כמושג אחד. וממילא יגדיר את הדבר שמצבו היה נמצא כך וכעת מצבו אחר כדבר אחד שהשתנה וכן דבר שמצבו כעת כך ובעתיד יהיה מצבו אחרת כדבר שישתנה.\u003c/span>"}, {"s": "h3", "h": "המעשה"}, {"s": "h4", "h": "מעשה כנושא את הנעשה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"72\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">22\u003c/sup>\u003cspan class=\"ca\" data-c=\"72\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">המעשה הוא הדבר הנושא את הנעשה, והיינו, שיחשב הדבר הנעשה במשמעות המעשה. וכן המעשה נחשב כנשוא של העושה, וכן המעשה הוא הדבר המקשר בין העושה לנעשה, וע\"מ להבין את המושג מעשה נצטרך להגדירו כנפרד מן העושה.\u003c/span>"}, {"s": "p", "h": "חילוק מעשה כגרימה מכח דמעשה - משמעות כח הפעולה בייחוס המעשה לעושה "}, {"s": "p", "h": "ונמצא בזה משמעות חלוקה ביחס לעושה, האחד, במשמעות היותו בעל המעשה. והשני, בשייכותו בתוצאת המעשה, ובזה יהיה גדר מעשה כגרימה, שאין משמעות בכוח אלא כסיבה מספקת, אך כמו שית' בע\"ה \u003csup class=\"cb\" data-c=\"73\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">23\u003c/sup>\u003cspan class=\"ca\" data-c=\"73\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">כיון שבשבת אין גדר המעשה גרימת התוצאה\u003c/span>, אין צורך שיהיה כוחו סיבה מספקת, דזה חסרון רק במעשה גרימה דתוצאה, אך בכוח דמעשה עצמו, משמעות כוח העושה הוא במה שנחשב המעשה לשלו [\u003csup class=\"cb\" data-c=\"74\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">24\u003c/sup>\u003cspan class=\"ca\" data-c=\"74\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וכמו שנמצא דדין שנים שעשו יהיה שייך אף בזורה ורוח מסייעתו\u003c/span>, כי אף שאין המעשה דשניהם יחד מסייע בכל מעשה הגרימה, עדיין יש לדון על כל אחד בגדר כוחו בזרייה לבדה]."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"75\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">25\u003c/sup>\u003cspan class=\"ca\" data-c=\"75\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ויסוד ביאור שני גדרים אלו, הוא בביאור גדר כוח שפועל במעשה שיש בו להחשיב את המעשה כמעשה שלו, ויוכרח כן באיסורי שבת, שהרי אין למצוא חסרון בהגדרת מעשה דחד משנים כמעשה איסור, היינו, מעשה דאי שביתה, ובהכרח שגדר חסרון בזה הוא משום משמעות שיש בזה בגדר המעשה עצמו שיחשב שנעשה מכח זה, ושאנו מחשיבים את המעשה עצמו כמו תוצאה, ובזה ימצא חסרון במעשה הנעשה בשנים. וגדר זה,  היינו, מה שכח אחד הוא רק חלק מגורמי המעשה, יהיה משמעות במעשה בשני פנים, האחד, במעשה כולו. והשני, בכל חלק מהמעשה. והחלק הראשון אין זה גדר בכח עצמו, אלא בגדר מעשה האדם, דהרי אין משמעות בכח הפועל בכל המעשה, שכל רגע ורגע יש להחשיבו ככח נפרד, והיינו, מה שנחשב המעשה של האדם, כיון שנעשה מכח שלו, וכיון שכך יש לחשב זה ביחס לאדם, היינו, מה נחשב לאדם מעשה שלו, וכיון שיש בכוחו לעשות המעשה כולו, הרי שלא עשה אלא מקצתו. אבל גדר החלק השני, היינו, כל חלק מהמעשה, אין זה גדר באדם אלא בכח, ואין משמעותו ביחס לכלל המעשה, שאין זה מגדרי כח, אלא כל חלק נבחן לעצמו וביחס להיותו כח הפעולה.\u003c/span>"}, {"s": "h5", "h": "המעשה כדבר הנעשה במציאות ועושה במציאות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"76\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">26\u003c/sup>\u003cspan class=\"ca\" data-c=\"76\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">והנה אחר הגדרת המציאות יבוא הגדרת המעשה, ואמנם יש לפעמים שמשמעות המציאות ביחס למעשה תבוא אחר הגדרת המעשה, אך אף בזה גדרי המציאות יקדמו לגדרי המעשה עצמו. שהמציאות ביחס למעשה היא הגדרה מוקדמת למה שנעשה במעשה.\u003c/span>"}, {"s": "h7", "h": "משמעות מעשה כמאחד חלקי מציאות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"77\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">27\u003c/sup>\u003cspan class=\"ca\" data-c=\"77\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">המעשה להבדיל מן המציאות יגדיר חלקי מציאות כאחד מה שלא ניתן לומר ביחס למציאות דהיינו ששני דברים במציאות המשפיעים אחד על השני לא יוגדרו במציאות כמושג אחד ולדוגמא שדבר מונח בתוך כלי ונחשיב את מונחות הדבר בתוך כמעשה של הכלי שיש לו תוך, הגדרה זו אינה הגדרה מציאותית גרידא כי אם נגדיר את הדבר כמציאות נפרדת נאמר ביחס לדבר שהוא מונח בכלי וביחס לכלי שהוא מכיל דבר אף לא יהיה בזה משמעות של מעשה הכלה של הכלי, אך בהגדרת המעשה יתאחדו חלקי המציאות ויוגדרו משמעויות השפעה בדברים.\u003c/span>"}, {"s": "h7", "h": "משמעות המעשה כהמשך וחיבור שלבי המציאות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"78\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">28\u003c/sup>\u003cspan class=\"ca\" data-c=\"78\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">המעשה גם יגדיר את המציאות שלפניו ואחריו כדבר אחד שהמציאות כפי שהגדרנו אותה אין בה יחס המקשר בין שלבי המציאות, והיינו, שאף שאמרנו ששייך להגדיר כחלק מהמציאות משמעות של שינוי, אין הכוונה שתהיה מציאות של שינוי כי המציאות היא הנמצא והשינוי ביחס אליה הוא עדיין רק מציאות. ואף כשנגדיר שינוי בדבר אחד במציאות הוא יוגדר בנמצא ולא כחלק מהמציאות המוקדמת, ולדוגמא כשנגדיר מציאות של חפץ שנעשה בו מעשה של שינוי והוא יצא ממקום למקום אחר, אף אם נגדיר משמעות אחת לשני המציאויות ביחס לחפץ, היינו, חפץ במשמעותו המקומית, נאמר שחפץ זה נמצא שלא במקומו וזה הגדרה בחפץ, או שנאמר זאת ביחס למקום על המקום הקודם שאינו מכיל את חפצו, או המקום הבא כמכיל חפץ שאינו חפצו, הגדרות אלו אינם הגדרות של שינוי אלא הגדרות מציאותיות לדבר נמצא.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"79\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">29\u003c/sup>\u003cspan class=\"ca\" data-c=\"79\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אך המעשה במשמעות מעשה דבר בדבר היא משמעות המשכית ויש בו איחוד חלקי המציאות לסיפור אחד, וההמשכיות יש בה משמעות של שינוי ומשמעות של חידוש, וכדוגמא כשנגדיר מעשה נוכל לומר שהחפץ עבר ממקום למקום, וממילא לא נצטרך לומר שהיה המקום הקודם מקומו, ואם נאמר שהמקום הקודם מקומו נוכל לומר שהחפץ עבר ממקומו למקום אחר או למקום שאינו שלו, כי משמעותו ההמשכית של המעשה כמאפשרת שני חלקי מציאות בבת אחת אינה מצריכה להגדיר את המציאות הקודמת כחלק ממשמעות המציאות הנוכחית. \u003c/span>"}, {"s": "h5", "h": "משמעויות הקיימות רק ביחס למעשה שהוא כהמשך"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"80\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">30\u003c/sup>\u003cspan class=\"ca\" data-c=\"80\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וכיון שאין גדרי המעשה כגדרי המציאות אלא יש להם משמעות של המשך על כן יוכלו להיות מושגים במעשה שלא יתכנו בהגדרת מציאות, כמו סיבה ומסובב, תיקון וקלקול, חידוש ושינוי, ושאר מושגים שמשייכים מציאויות לגדר אחד ויוכל להגדיר את עושה המעשה כמקיים את המציאות המחודשת או כיוצר את השינוי המחודש.\u003c/span>"}, {"s": "p", "h": "וע\"מ להבהיר את הדברים נתייחס למציאות מעשה של דבר הנמצא בדבר."}, {"s": "h7", "h": "מקרה שני דברים כמעשה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"81\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">31\u003c/sup>\u003cspan class=\"ca\" data-c=\"81\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">יש ומציאות של שני דברים בעצם צורת המציאות ומשמעותה תחשב למעשה, ולדוגמא מעשה של קירבה שאין הקירבה מעשה של אחד מהמתקרבים אלא הוא הגדרה כוללת ביחס לשאר דברים וזה יחשב מעשה, ואם יעשה זאת שלישי בשני דברים יחשב שעושה המעשה ואם יעשה אותה אחד מהמתקרבים יחשב מעשה שלו אף שגדר המעשה הוא בשניהם בלי יחס השפעה, ובדוגמא שלנו של דבר הנמצא בדבר אחר יהיה משמעות קירבה שאינה נחשבת של אחד מהמתקרבים.\u003c/span>"}, {"s": "h7", "h": "מקרה דבר בדבר אחר כמעשה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"82\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">32\u003c/sup>\u003cspan class=\"ca\" data-c=\"82\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">יש ומציאות של דבר בעצם קיומו ובהיות בו מקרה דבר ומשמעות שיש בזה תחשב למעשה, ולדוגמא מעשה של קירבה באופן שהקירבה היא מעשה של אחד מהמתקרבים, ואם יעשה זאת שלישי בשני דברים יחשב שעושה המעשה ואם יעשה אותה הקרב או האחד שאליו קרבים יחשב מעשה שלו אף שגדר המעשה הוא במתקרב או באחד שאליו קרבים , ובדוגמא שאמרנו של דבר הנמצא בדבר אחר יהיה משמעות קירבה בדבר ככלי בית בחצר שאינה מעורבת.\u003c/span>"}, {"s": "h5", "h": "המעשה ביחס למציאות קיימת"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"83\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">33\u003c/sup>\u003cspan class=\"ca\" data-c=\"83\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">המעשה לפעמים יהיה כולל רק את המציאות הנוכחית, והיינו, שעצם השינוי בקיום המציאות המחודשת אינו חלק מהמעשה אלא רק הקיום עצמו והשייכות בין העושה לנעשה, ודוגמא לזה הוא מעשה בחלבים ועריות שמי שנתן חברו חלב בתוך פיו חייב שכן נהנה אף שלא עשה מעשה (רק לא מנעו), והיינו, שהיות החלב נאכל ע\"י אדם הוא התוצאה וההנאה היא העשייה והאדם הנהנה הוא העושה, וכל החלקים הללו באים כאחת, ואינם דורשים שינוי שהרי השינוי נעשה ע\"י אחר אלא שעצם הקיום של אדם אוכל חלב הוא חלק המציאות והמעשה הוא ההנאה (הנה ביחס לנהנה מחלבים ועריות היה נראה שאין ההנאה נחשבת כנגרמת ע\"י העושה אך מצאנו תוס' בסנהדרין סה שחולק בזה). ואמנם להגדיר את המעשה כמקיים את המציאות ודאי דרוש החידוש שיש במעשה אך חידוש זה נדרש רק בכדי להגדיר כנ\"ל את המעשה שהוא מקיים שזה המושג מעצם מהותו נוגע לדברים המשתנים, אך אינו דרוש כגורם את המציאות המחודשת.\u003c/span>"}, {"s": "h7", "h": "המעשה כגורם את התוצאה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"84\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">34\u003c/sup>\u003cspan class=\"ca\" data-c=\"84\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">לפעמים יהיה המעשה כולל משמעות שהוא גורם את המציאות המחודשת, והיינו, שצריך שיהיה המעשה סיבה לקיום התוצאה וממילא גם העושה\u003c/span>"}, {"s": "h7", "h": "המעשה כממציא מציאות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"85\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">35\u003c/sup>\u003cspan class=\"ca\" data-c=\"85\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">לפעמים יהיה המעשה רק במשמעות של המצאת המציאות, והיינו, שלפני המעשה לא היה המציאות הנעשית, והמעשה יעשה שתהיה. ויהיה המעשה מגדיר את המציאות הנוכחית ביחס למציאות הקודמת כדבר שהומצא, ואת העושה כממציא דבר.\u003c/span>"}, {"s": "h7", "h": "המעשה כחידוש מצב בדבר קיים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"86\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">36\u003c/sup>\u003cspan class=\"ca\" data-c=\"86\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">לפעמים יהיה המעשה ממציא מצב בדבר קיים דהיינו שיהיה שם הדבר שאליו מיוחס המעשה אחד לפני ואחרי המעשה, אלא שישתנה מצבו מבחינה מסוימת ובזה לא יהיה המעשה נחשב אלא אם גרם מציאות אחת להיות מציאות אחרת ובמעשים כאלו הנבחנים בשינוי, גרימת מציאות מחודשת של הדבר עם המצב ללא עצם השינוי לא יחשבו כמעשה, כי כאמור יהיה המעשה עצם המצאת הדבר הקיים במצב חדש, והיינו, כי יהיה המעשה בדבר.\u003c/span>"}, {"s": "h7", "h": "המעשה כשינוי מצב הדבר"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"87\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">37\u003c/sup>\u003cspan class=\"ca\" data-c=\"87\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">לפעמים יהיה המעשה שינוי בדבר קיים ממצב למצב, והיינו, שלא יהיה במצב החדש מציאות חשובה ביחס למעשה כי עצם המצאת המצב החדש בדבר לא תהיה מעשה אלא מעשה השינוי עצמו וגדר מעשה זה הוא בדבר שיהיה חשיבות בדבר בעצם יציבות מצבו ללא שינוי והמעשה המביאו למצב חדש הוא עצם עשיית השינוי.\u003c/span>"}, {"s": "h5", "h": "הגדרות שאינם משמעות במעשה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"845\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">38\u003c/sup>\u003csup class=\"cb\" data-c=\"88\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">39\u003c/sup>\u003cspan class=\"ca\" data-c=\"845 88\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">והנה מעשה אף שהוא הגדרה כללית של מקיים מציאות, גדר המעשה המסוים ישתנה בכל מקום לפי עניינו, ולכן הוא אינו תלוי באחידות הפעולה מבחינת הפועל או מבחינת כמות הפעולות ולפעמים יהיה חלק מכמה פעולות מחוברות או נפרדות וכן יהיה תלוי במעשים אחרים כחלק מהגדרתו שגדר פעולה הוא גדרו של העושה ולא של המעשה.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"846\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">40\u003c/sup>\u003cspan class=\"ca\" data-c=\"846\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">העושה\u003c/span>"}, {"s": "p", "h": "העושה כמרכיב במעשה נחשב כמי שעושה, היינו, שהמעשה והתוצאה הינם מושא בעושה, והוא נושאם, וזה יהיה בכמה אופנים. ויש בזה כמה חלקים, והיינו, שככל שנגדיר את המעשה והתוצאה, כך יוגדר העושה."}, {"s": "h4", "h": "העושה כנושא המעשה"}, {"s": "p", "h": "העושה כנושא המעשה אינו מחייב שיהיה אדם או בעל רצון ויש שיחשב העושה דבר דומם ואף ביחס לאדם יש שיחשב עושה ולא מחמת היותו אדם, והיינו, שיש להחשיבו עושה רק מחמת שהמעשה נעשה בגופו של הדבר. ויש מעשים ויחשבו כמעשה של הדבר רק אם הוא סיבת היותם, היינו, שהוא הגורם למעשה והתוצאה."}, {"s": "h4", "h": "אדם העושה"}, {"s": "p", "h": "גדר אדם העושה ביחס למעשה הוא שאמרנו, שיש שיחשב עושה מחמת משמעות המעשה ביחס אליו, ויש שיהיה העושה נחשב כך כי הוא הגורם למעשה או כגורם המציאות."}, {"s": "p", "h": "וגדר העושה לעצמו, היינו, מה יהיה העושה ביחס למעשה, ואם יהיה זה חי העושה יהיה נדרש שיהיה חי. ואם זה אדם יהיה נדרש שיהיה אדם."}, {"s": "p", "h": "ויש באדם העושה שני חלקים, אחד הוא המחשבה וזו עשייה שבדעתו, לחשוב כך או אחרת. והמעשה במציאות, וזו העשייה שבגופו, ולא יחשב האדם כאדם העושה אלא אם יש בו כח המחשבה, והיינו, שהוא בר דעת."}, {"s": "h6", "h": "דעת האדם"}, {"s": "p", "h": "הדעת היא מקום הידיעות ופעולת המחשבות כמו שהמציאות הגשמית היא מקום הדברים ופעולת המעשים, ופעולת מחשבה בדעת האדם תיצור שינוי בדעת כמקום הידיעות, וההמחשבה החדשה תקרא דעתו ביחס לנושא הידיעה, ואם לא יהיה בו הדעת לא יהיו מחשבותיו בגדר מחשבה, והדעת עצמה היא היכולת להשיג מושגים וידיעות על המציאות והקשר ביניהם והיותם יציבים לאורך זמן, וזה יהיה גדר בדעת עצמה, ואם לא יהיה האדם בעל יכולת זו מחשבתו לא תחשב מחשבה."}, {"s": "h7", "h": "דעה מקולקלת"}, {"s": "p", "h": "ואם תהיה הדעה שלו מקולקלת ביחס להשגת הידיעות או המושגים או הקשר ביניהם לא תהיה מחשבתו מחשבה שכיון שדעתו אינה קיימת כראוי לא תהיה המחשבה יותר מדעתו עצמה, וזה השוטה. "}, {"s": "h7", "h": "דעת פחותה"}, {"s": "p", "h": "וכן יש ויהיה האדם בעל דעה פחותה, שאינה משיגה אלא דעות מסוימות ולא דעות אחרות, וגם בכמות שהשגתו אינה מאפשרת אלא ידיעת כמות מסוימת של ידיעות, אך תהיה נכונה וקיימת בבסיסה ודלא כהשוטה הנ\"ל. ולכן יש שבמחשבות מסוימות שצריכים את דעת שלימה לא תהיה מחשבתו כמחשבת דעת, אך יתכן שתחשב דעתו כדעה למחשבה אחת ולא למחשבה אחרת, וזה יש כמה דרגות בקטנים עד גיל עשרים, ובחרשים ונשים."}, {"s": "p", "h": "והדעת הנ\"ל היא מקום כולל לכלל מחשבות האדם שיהיה האדם נהנה ושמח ומצטער ועצוב ושאר דברים מעין אלו."}, {"s": "h7", "h": "דעת כבעלת ידיעות"}, {"s": "p", "h": "והדעת תכיל את הידיעות שיש לאדם הן באופן כללי, מה שישיג המושגים ואת הידיעות הפרטיות על דבר מסוימים מה הם וקיומם. והן ביחס למעשים מה יגרמו או מה יהיה משמעויות דבר קיים וכו'."}, {"s": "h6", "h": "בקשה"}, {"s": "p", "h": "הבקשה היא מחשבת הצורך, היינו, שיהיה בדעת האדם שצריך הוא בשימוש וכדוגמא שיחשוב האדם שצריך הוא באכילת דבר מסוים או בהנאת דבר מסוים, אבל לא תהיה המחשבה באיזה דבר הוא אלא בסוג הדבר שאם צריך הוא לאכילת תאנים כיון שהמחשבה נוגעת לאכילה עצמה כל הדברים, היינו, התאנים יחשבו לדבר אחד, כי המחשבה היא בשימוש."}, {"s": "h6", "h": "מחשבה"}, {"s": "p", "h": "הדעת כאמור היא מקום המחשבות והמחשבות יהיה כוללים התייחסויות למציאות ולמעשים, והיינו, שיהיה האדם חושב על דבר מסוים ביחס למשמעותו השימושית, והיא התייחסות לדבר קיים והתייחסות לדבר שעדיין לא קיים. התייחסות למציאות הוא לדוגמא שאם אדם יחשוב שיהיה הדבר כלי או שיהיה הדבר תרומה נחשב התייחסות למציאות קיימת שאין דרוש שינוי בדבר אלא רק מחשבת משמעותו. והתייחסות למעשים, היינו, לדבר שאינו קיים כמו שיהיה דבר חדש ובמובן זה תחשב התוצאה העתידה פרי המחשבה שהיא נחשבת כגרמה לו, והמחשבה היא העיסוק בדבר במשמעותו כשהוא ממלא צורך. "}, {"s": "h6", "h": "רצון"}, {"s": "p", "h": "הרצון הוא מחשבת קיום מציאות, והיא משם רץ כאדם הרץ אל מקום אחד ואף שבזמן שהוא רץ אין הוא עדיין במקום כיון שהוא בדרכו אל המקום ביחס למקומות שאפשר לו להיות בם יש עליו שם המקום ההוא יותר משאר מקומות וכן באדם שיש בדעתו ידיעה לגבי המצב הראוי להיות בו וכשירצה, היינו, שיחשוב קיום מצב כראוי לו יקרא שרוצה במצב ויהיה עליו שם הדבר שרוצה, וזה גם בזמן המצב ביחס להמשכו. "}, {"s": "p", "h": "אך אם לא יהיה רוצה, היינו, שחושב בדעתו על אי קיום המצב כראוי לו הוא יחשב אנוס ביחס למצב, והיא משם נס כאדם היוצא ממקום שאף שהוא עדיין במקום שכיון שהוא בדרכו לצאת מן המקום ביחס למקומות שאפשר לו להיות שם יהיה עליו פחות שם שהוא במקום הזה, וכן באדם שאנוס על המצב לא יהיה עליו שם הדבר שאנוס בו וגם זה אף בזמן המצב ביחס להמשכו."}, {"s": "p", "h": "וכן הוא ביחס למעשה, היינו, קיום מציאות המעשה שיחשוב אדם קיום תוצאת המעשה כראויה לו יחשב כרוצה את המעשה וכן לאידך אם אנוס עליו."}, {"s": "p", "h": "וכיון שמשמעות אונס ורצון מתייחסים לקיום מציאות יתכן שיעשה אדם מעשה ברצון למעשה אך לא יחשב כך ביחס לתוצאה, וכן ביחס לאי עשיית דבר שכיון שהאונס מתייחס למציאות לא יהיה האנוס כמי שעשה, אך ביחס למציאות שנמצא שלא עשה, שייך שיהיה אנוס עליו, ונפרט."}, {"s": "h7", "h": "ביחס למציאות מתחדשת"}, {"s": "p", "h": "אם נחשוב מעשה כגורם נחייב שיהיה המעשה ברצון. וזה יתחלק לפי המעשים, שאם נחשוב מעשה כקיום מציאות נוכחית, אז יספיק שיהיה האדם רוצה את קיום המציאות. ואם נחשוב מעשה כמקיים התוצאה, נצטרך שירצה את התוצאה. וזה ישתנה לפי גדר המעשה. ולדוגמא, באיסורים שאינם עניין לגרימה אלא רק עצם המצב האסור, כמו נהנה מחלבים ועריות, אף שהאדם לא יהיה הגורם, כיון שההנאה היא מרצונו הרי זה נחשב רצון."}, {"s": "h7", "h": "ביחס לעשיית המעשה"}, {"s": "p", "h": "ובדברים שצריך שיהיה האדם גורם, ויש משמעות גם למעשה עצמו בלא חשיבות הנובעת ממטרת המעשה, אז המעשה צריך שיהיה לרצונו, וכדוגמת שבועת שווא, שמשמעות האיסור היא השבועה על דבר שהוא שקר, אם נאנס על דבר שקר לחשוב שהוא אמת נחשב כאנוס, ולא נחשב שנשבע על שקר. ואף שבאמת הוא שקר, כיון שהאיסור הוא להישבע, היינו, לאמת דבר שהוא שקר, הרי שאם היה בדעתו הדבר כדבר אמיתי, אז לא יחשב השבועה כשבועת שקר. והיינו, שאין האיסור שיהיה שבועה על שקר, אלא שאמירת השבועה תהיה במשמעות של אימות שקר. וכיון שהמשמעות של שקר ואמת היא ביחס לידיעת האדם, אם זו היתה ידיעתו הרי שהוא אנוס."}, {"s": "p", "h": "והנה מצאנו בזה שני דוגמאות הפוכות חלבים ונזיקין, דחלב נאסר אפילו הוא לא גורם למעשה, אבל אינו חייב אלא ברצונו ולא באונס. ונזיקין חייב אפילו אם נעשה באונס, אבל אם אינו גורם למעשה אינו חייב."}, {"s": "p", "h": "והיינו, שבשני מקרים (וגדר זה בחלב הוא לדעת חלק מהראשונים) מצאנו את שני החלוקות האמורות באופנם הטהור, והיינו, שמלבד מה שנצטרך שיהיו המעשים נעשים בגוף העושה, בנזיקין, הוגדר מעשה ביחס לעושה רק מחמת גרימתו את המעשה, ולא מחמת היותו רוצה וכו', ולכן יחשב כעושה ככל שתוגדר גרימתו. ובחלב, הוגדר המעשה ביחס לעושה רק מחמת רצון העושה את המעשה, ולא מחמת גרימתו אותו, ולכן יחשב כעושה ככל שיוגדר רצונו."}, {"s": "h6", "h": "כוונה"}, {"s": "p", "h": "הכוונה היא שם כללי למחשבה בדבר מסוים, לשם דבר אחר, והוא משם כיוון, כדבר המכוון ומתאים לדבר אחר."}, {"s": "h7", "h": "ביחס למציאות"}, {"s": "p", "h": "ובדברים שצריך שיהיה האדם עושה למטרה, צריך שיהיה עשיית המטרה לרצונו, שצריך שבמעשה עצמו יהיה רצון למטרה בכדי שיחשב שהמעשה נחשב כמעשה למטרה זו. ולדוגמא כוונה במצוות, שאם נאמר שמצוות צריכות כוונה, היינו, שלא מספיק שיהיה האדם עושה את מעשה המצווה, אלא צריך שיהיה המעשה עצמו יהיה לשם דבר אחר. היינו, קיום מה שה' ציווה. וזה שייך גם בדברים שאין צריך שיהיה גורם להם אלא שהאדם עצמו צריך שיעשה אותם בעצמו, כמו שמיעת קול שופר, והיינו, שמעשה התקיעה לא יעשה אותו הוא אלא רק מה שישמע, ואם צריך כוונה אז צריך שיהיה עושה השמיעה לשם מצווה, היינו, לקיים הציווי שציווהו ה' לשמוע קול שופר. והיינו, ששמיעת הקול תחשב שמיעה בכל אופן, גם אם לא יכוון למצווה, אבל צריך שירצה לצאת ידי חובה בזה. וזה משמעות המילה כוונה, שיש את גוף המעשה, ויש בו משמעות של קיום מצווה, ומה ששומע הוא גוף המעשה, והרצון במשמעות הוא הכוונה."}, {"s": "h7", "h": "ביחס למעשה"}, {"s": "p", "h": "וכן לגבי דברים האסורים משום התוצאה שנעשית, שצריך שיהיה רצון במעשה שיצא ממנו התוצאה. וגם זה נחשב כוונה שתהיה הפעולה בכוונת התוצאה."}, {"s": "h7", "h": "ביחס למעשה בעל משמעות"}, {"s": "p", "h": "ובדברים שיש משמעות לעצם המעשה שהוא עושה את התוצאה, והיינו, שיהיה המעשה במשמעות שהיא מובילה לתוצאה, אז יהיה הרצון לתוצאה חלק מגדר המעשה עצמו, ואם לא יהיה הרצון לתוצאה, אז המעשה עצמו יהיה חסר במשמעותו כמעשה, ואפילו יוביל המעשה לתוצאה, ואפילו ידע שהמעשה מוביל לתוצאה, לא יחשב המעשה כמעשה, כיון שלא רצה שיהיה המעשה מוביל לתוצאה. וכוונת מעשה לתוצאה תהיה בגדר רצון במעשה עצמו, והיינו, שיהיה במחשבת התוצאה."}, {"s": "h4", "h": "סיכום"}, {"s": "p", "h": "ונמצאנו א\"כ ארבעה גדרים בדעת והם הבקשה, המחשבה, הרצון והכוונה. הבקשה, היא יחס הדעת להיות האדם צריך שימוש, והיא התייחסות לעצמו כצריך. המחשבה, היא יחס הדעת ביחס למשמעות דבר קיים או שיהיה קיים כממלא צורך, והיא התייחסות לעצם הדבר כממלא צורך הבקשה. רצון, הוא יחס הדעת לדבר שיתקיים כמציאות במשמעות המחשבה, ובזה שייך דיני אונס ורצון. כוונה, יחס הדעת לדבר ביחס לדבר אחר, וכמו שיחשוב בזמן פעולה שהדבר שבו נפעל יהיה דבר אחר."}, {"s": "p", "h": "וכן יתחלקו מושגים אלו לפי משמעותם לגדרם, שהבקשה, כיון שאינה מתיחסת לדבר אלא לעצמו, אין צורך שיהיה חושב בה ביחס לדבר, או בזמן עשיית הדבר. והמחשבה, שאינה מחשבה אלא בדבר, אזי כל שחשב בה ביחס לדבר תקרא מחשבה, אך תשתנה בגדריה לחשיבה דעתו של אדם לפי הבנת המציאות שבה, שאם חשב מחשבה על דבר וטעה בידיעתו על הדבר לא תחשב מחשבתו, וכן לפי יציבות המחשבה הנקראת גמירות דעת שאם יחשוב עכשיו כך ובזמן אחר יחשוב כך לא תחשב מחשבתו כדעתו. אך הרצון, כיון שהוא התייחסות ביחס לתוצאה מסוימת, כל זמן שירצה נחשב רצון ביחס לזמן ההוא, ואם התרצה בעת המעשה כולו יחשב שנעשה ברצון, אף אם ברור שישתנה רצונו לאחר מכן. ובכוונה, היינו, כוונת דבר אחד לדבר אחר, יהיו שני הדברים צריכים להיות חלק מהכוונה, ואם יהיה זה כוונה של מעשה לתוצאה, אז צריך שיתכוון בזמן המעשה שתעשה התוצאה. "}, {"s": "h4", "h": "העושה מעשה מצווה"}, {"s": "h7", "h": "ידיעת משמעות המצווה במעשה"}, {"s": "p", "h": "והנה כל זה אמרנו ביחס להיות האדם עושה המעשה, אך בנוגע למצוות התורה ישנה משמעות לעשיית מעשה שהוא בלא תעשה. והיינו, שביחס לעשיית המעשה האסור ישנה עוד הבחנה, אם יודע שעושה מעשה אסור, שהיודע שעושה מעשה אסור ועשאהו נקרא מזיד, ואם לא ידע שהמעשה אסור נקרא שוגג. "}, {"s": "h7", "h": "ידיעת איסור לא תעשה"}, {"s": "p", "h": "ויש לנו לחלק בגדר מחשבת שוגג ומזיד באיסור לא תעשה, לבין שאר מחשבות בגדרי עשייה, וכן ביחס למצוות עשה. והיינו, שהתייחסות למעשה בבחינה האם הדבר נעשה, וע\"י מי, וכו', אינו דומה לבחינת מחשבה של מעשה שנאמר עליו שלא לעשות. שבציווי של אי עשייה יש בו התייחסות לכלל הזמנים והמקרים שלא יהיו בגדר עשייה אסורה זו, וכיון שכך הרי שמי שעשה במזיד הרי הוא ככל עושה מעשה ביחס לאיסור. אבל מי שעשה בשוגג הרי שאיסורו הוא איסור בכלל המקרים, שלא ראה להפריש מעשה זה מכלל מעשיו. וא\"כ מלבד גוף האיסור יש בשוגג מעשה בדעת עצמה, ביחס למעשים שנעשים."}, {"s": "h7", "h": "איסור לאו ביחס לכלל דעת המקרים"}, {"s": "p", "h": "ועל כן הדעת תהיה משמעותית ביחס לגדרי האיסור, שיצטרך ידיעה בתחילה, ויהיו ידיעות מחלקות וכו'. וכיון שאיסור לא תעשה נוגע לכלל המעשים, יהיה חלוקה בדעת גם ביחס לדברים שבהם נעשה האיסור כגופים וכו', כי מחמת האיסור היה לו להיזהר בגוף זה שלא לעשות מעשה זה. וככל שיהיה בהגדרת האיסור משמעות פרטית ביחס לחלקי המעשה, הן המעשים עצמם כביאה ואכילה והנאה וכו', והן בגופי האיסור, תהיה חלוקה בדעת ביחס לאי עשייתם, ויתחלקו בזה ביחס לאשמת האדם."}, {"s": "p", "h": "שלושה חלקים בעשייה ויחסם ללאווין - האדם, מעשה האיסור, והדבר האסור "}, {"s": "p", "h": "וימצא בזה (היינו, גדר עשייה האסורה) שלושה חלקים בעשייה, והם האדם, המעשה האסור, והדבר האסור. והשמר הוא ביחס לאדם, וזה שייך בשמירת עצמו, וביחס לכלל מעשיו, ובשמירה מדבר אסור, אבל מילת פן אין היא אלא ביחס לדבר שאפשר לו להתקיים או לא. וע\"כ לא תבוא ביחס לאדם אלא אם יוגדר מצב שבו יתכן לאדם להיות או לא, ואם נאמר פן תעשה יהיה פירושו שביחס לעשייה תהיה לפניה ולא אחריה, והיינו, ביחס לשני המצבים בהם אתה נמצא עם העשייה ובלעדיה. ומילת אל תיתכן ביחס לאדם ושייכותו לדבר האסור, אם מעשה ואם חפץ, אבל לא לקיומו, אלא לאי קיומו [וזה ביאור מה שאמרה שכינה כן ירבה, היינו, שאין ישראל נמצאים במצב שעדיין אינם מתרבים, אלא מצבם הנוכחי הוא במצב ריבוי וישאר על כנו ואין זה תלוי בהתחכמות מצרים]."}, {"s": "h4", "h": "סיכום"}, {"s": "p", "h": "וא\"כ מצאנו בגדרי עושה כמה דברים, גוף העושה, דעת העושה, הידיעות בדעת העושה, מחשבה כהגדרת מציאות, רצון ביחס למציאות מתחדשת וביחס לתוצאה, כוונה, ביחס למציאות, ביחס למעשה, ביחס למעשה בעל משמעות, וביחס לעושה מעשה מצווה, ידיעת משמעות המצווה במעשה. דעת מעשה האיסור ביחס לכלל המעשים."}, {"s": "p", "h": "(לפ\"ז יחולקו דיני המעשה, דחיוב חטאת הוא משום אי הזהירות, והפטור דחטאת הוא משום שלא היה לו להיזהר בזה. וחיוב מלאכה הוא משום עשייתו, והפטור דמלאכת מחשבת הוא משום שאינה עשייה. והפטור דאינו מתכווין הוא משום שאינו מעשה אסור. והכלל דחיוב חטאת הוא חיוב כללי על האדם שיהיו מעשיו מכוונים.)"}, {"s": "h3", "h": "גדרי איסור מעשה"}, {"s": "h4", "h": "גדרי מעשה"}, {"s": "p", "h": "הנה מצאנו בתורה כמה שמות מעשה, וחלוקתם במעשה, ובתוצאה. בעושה, ובנעשה. שיש מעשים שנקראים ע\"ש גדר שיש במעשה בעושה או בנעשה, בעושה כמו רדיה במי שרודה וזניה במי שזונה וכו', או בנעשה כמו הורדה במוריד והקמה במקים וכו'. ויש מעשים שנקראים ע\"ש גדר שיש בתוצאת המעשה בעושה או בנעשה, בעושה כמו טומאת עצמו במיטמא, ובנעשה כמו טומאת אחרים במטמא והינוח דבר במניח. וכן יש מעשים שנקראים ע\"ש גדרם בעשיית הנעשה כעושה מעשה כמו הזנייה במי שמזנה אחר (אל תחלל וכו' להזנותה) והפנייה במי שמפנה אחר (כהפנות שכמו). וכן מצאנו שמות מעשה ותוצאה כלליים כמו לא תעשה ולא יהיה. וכן מצאנו שהשייכות בין העשייה לנעשה תבוא בכמה גדרים דבר, בדבר, אל דבר, מדבר, לדבר, את דבר, על דבר, כל דבר, וחילוקם כך. בדבר, מה שיש במעשה להיות כלול בדבר ככח בחפץ, וכדבר במקום. אל דבר, מעשה ביחס לדבר החלוק ושאין במעשה להכלילו. מדבר, מעשה שיש בו להוציא מן הדבר בלי לשנות גדרו, ככח דבר, או כמלאות דבר. את דבר, על דבר, כל דבר, הוא גדר במעשה או בתוצאה שיש בחלקה גדר ככולה כי כללה הוא כלל חלקיה, ויתבאר לקמן. וכן מצאנו שהשייכות בין העושה למעשה תבוא בכמה גדרים כמו בדבר סתם, תעשה לך, וכן מצאנו שהשייכות בין העושה לנעשה תבוא בכמה גדרים כמו דבר, דברך או דברו, דבר דבריך או דברי דבריך, דבר לך. "}, {"s": "h4", "h": "גדרי העושה"}, {"s": "p", "h": "והנה במעשים שהעושה הוא חלק מהמעשה, כמו נגיעה וביאה ואכילה וכו', אין גדר המעשה האסור דבר לעצמו, וע\"כ יהיה חלוק המעשה מהעושה, אף שיהיה העושה וגופו חלק מהנעשה, וכמו אכילה שהוא גדר בעושה כנעשה. וע\"כ יהיה גדר באדם כאינו בעל המעשה, וכמו שאמרו שחלבים ועריות חייב אפילו במתעסק שכן נהנה, והיינו, דכיון שאסרה תורה מעשה שגופו של העושה הוא חלק מן המעשה, הרי שיש גדר בעשייתו כנעשה ולא כעשייה. אך במעשים שאין הם מחמת עשייתו אלא מחמת הנעשה, כמו רציחה, היינו, שפיכות דמים דנרצח, לא יהיה משמעות באדם כחלק מהנעשה אלא כעושה גרידא. ולא תרצח הוא כאילו אמר לא תהיה רצח. "}, {"s": "p", "h": "ועכ\"פ מצאנו כמה חלקים במעשה. העושה, המעשה והתוצאה. והמעשה חלוק לעשייה, ומה שנעשה, וכגון ברציחה, העושה נקרא רוצח, והמעשה חלוק, העשיה רציחה, והנעשה נרצח, והתוצאה בעושה רצח, ובעשוי רצוח. (ואמנם לא מצאנו לשון עשוי, היינו, רצוּחַ. כי הרציחה בנפש איש, והנפש הרוגה, והאיש מת, והאדם חלל, והדם נשפך, ובשרו נבול. ואין זה דבר אחד שהוא רצוח) וכן באכילה, שהעושה אוכל, והעשייה אכילה, והנעשה נאכל, והתוצאה בעושה אכל, ובעשוי אכול. (ולא מצאנו לשון עשוי כי אינו אחר שנאכל) ובמעשים האסורים מחמת היות הדבר העשוי, וכן להיפך במעשים שהם יצירת דבר חדש שאינו קיים לפני המעשה, כמו פסל ומלאכה. ובעושה יהיו שלושה גדרים אפשריים, גופו, דעתו, ורצונו. ובמעשה יהיו שלושה גדרים, העשייה, הנעשה, ומשמעותם האחידה. ובתוצאה יהיו שני חלקים בעושה ובנעשה. ועוד יתבאר בעז\"ה."}, {"s": "h4", "h": "איסור לא תעשה"}, {"s": "p", "h": "איסורי לא תעשה מחולקים לשלושה באי עשייה, בשמירת מעשה, ובמניעת קיום. אי עשייה היא באדם העושה וגדרה החיובי הוא שמירת עצמו כעושה, ושמירת העושה היא בשלושה גדרים שמירת האדם הכוללת שמירת גופו דעתו ורצונו, שמירת מעשיו, ושמירת תוצאותיו, ושמירת העושה בגופו כדוגמת חלבים ועריות שלא יהנה גופו מהם, ובדעתו כדוגמת מחשבת איסור וכוונת ד' דברים, ורצונו כדוגמת לא תחמוד ופנית הלב, ושמירת מעשיו כדוגמת רוצח בשגגה, ושמירת תוצאותיו כדוגמת מזיק. ושמירת מעשה היא בדבר שעשוי, היינו, שאין הוא מכוח המצוּוֶה ואף שיתכן שנעשתה על ידו אבל קיומו אינו תלוי בו כמו חילול קדושת השבת ומעילה בקודש אבל שמירת מעשה שכוללת עשייה הרי היא מצוות עשה. ומניעת קיום הוא בעשייה, ובמעשה, ובדבר, בעשייה בדר\"כ יהיה על אחרים שעשייתם שייכת אליו מחמת שהם שייכים אליו או שעושים ע\"פ או לכלל הציבור כאחראי על הנעשה בתוכו, וכן במעשה ששיכותם אליו מחמת בעל העשייה או הדבר הנעשה וכן בציבור כאמור, ובדבר שהוא ברשותו וכו'. ויש מן המצוות הכוללות כמה גדרים שונים, ובשבת מצאנו גדר אי עשייה דאיסור עשיית מלאכה, וגדר שמירת מעשה דקדושת השבת, וגדר מניעת קיום, בעשייה, דבנך ובהמתך. ובמעשה, בשביתת כלים לב\"ש."}], "comments": [{"id": "841", "n": 1, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-044 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (1 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. מלאכת הוצאה - הקדמות וכללים\u003c/p>"}, {"id": "55", "n": 2, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0072 | חומרה: בינונית | קטגוריה: סדר מושגים והגדרת מלאכת הוצאה. המשפט מציג שלושה „מושגים” – מעשה, מלאכה ומושגי הוצאה – אך הם אינם מקבילים באותה רמה: „מעשה” ו„מלאכה” הם מושגים כלליים, ואילו הוצאה היא מלאכה מסוימת/תחום הלכתי מוגדר. כדאי להבהיר אם כוונת המחבר היא לפרק את מלאכת הוצאה לשלושה מישורים (מעשה, גדר מלאכה, וגדרי רשויות/מקום), או להבחין בין המושג הכללי „הוצאה” לבין גדרי המעשה. גם הניסוח „מושגי הוצאה” דורש פירוט אילו מושגים נכללים בו.\u003c/p>"}, {"id": "56", "n": 3, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0073 | חומרה: גבוהה | קטגוריה: הגדרת מעשה ובהירות. ההגדרה „המעשה כולל שלושה מרכיבים: העושה, התוצאה ואת התעסקות העושה בתוצאה” אינה ברורה עדיין. מהי „התעסקות העושה בתוצאה” ומה ההבדל בינה לבין המעשה עצמו? האם התוצאה היא מצב סופי, שינוי במציאות, או דבר שעליו חל שם מלאכה? בהמשך (פסקאות 213 ואילך) המחבר מבחין בין כוח הפועל, חלקי המעשה והתוצאה; כדאי להציג כבר כאן הגדרה יציבה שתשמש לאורך הפרק, ולא להחליף בין „מעשה”, „פעולה”, „התעסקות” ו„תוצאה” ללא הבחנה.\u003c/p>"}, {"id": "57", "n": 4, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0074 | חומרה: גבוהה | קטגוריה: הגדרה מעגלית וסתירה אפשרית בהמשך. הניסוח „המושג מעשה כדבר שהתחדש הוא המציאות בעלת המשמעות” אינו מגדיר בבירור מהו מעשה: האם מדובר במעבר ממצב קודם למצב חדש, בקשר סיבתי בין מצבים, או במשמעות שאנו מייחסים למציאות? בהמשך (פסקאות 219–220) נאמר שהמעשה מחבר את המציאות שלפניו ואחריו ומאפשר לדבר על שינוי והמשכיות. מומלץ להקדים כאן הגדרה תמציתית של מעשה כיחס/תהליך בין מצבים, ולהבחין בינה לבין התוצאה שהיא המצב שהתקבל; אחרת ההגדרה הנוכחית קרובה למעגלית.\u003c/p>"}, {"id": "58", "n": 5, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0075 | חומרה: גבוהה | קטגוריה: הבחנה בין מושג מציאותי למושג הלכתי. החלוקה בין מושגים מציאותיים („חפץ”, „מקום”, „מונח במקום”) למושגים שימושיים („אוכל”, „מקום חשוב”, „רשות”, „רשות הרבים”) דורשת סייג. „רשות הרבים” ו„רשות היחיד” הן קטגוריות הלכתיות בעלות תנאים מבניים ושיעורים מוגדרים (גובה, מחיצות, רוחב, שימוש הרבים ועוד), ואינן רק מושגים שימושיים התלויים בתכלית או בתפיסת האדם. יש להפריד בין המציאות הפיזית, השימוש בפועל, וההגדרה ההלכתית של הרשות, ולהבהיר באיזה מובן „רשות” היא מושג שימושי.\u003c/p>"}, {"id": "842", "n": 6, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-045 | סוג: חיבור עצמאי | מקור: קבצים ערוכים להטמעה (פרק א חלק ד' במסמך הבדיקה)\u003c/p>\u003cp>כותרת מוצעת בסגנון הכותרות שבקובץ: שורשי לשון הקודש בהגדרת המעשה, הרצון והמקום - נטל, נתן, רץ וצר, קום ומקום\u003c/p>\u003cp>חיבור עצמאי בבלשנות למדנית ושורשי לשון הקודש, שהוכן להטמעה ולא הוטמע. מקום השילוב הטבעי: כהרחבה בלשנית-שרשית לניתוח המושגים שבמושגי המציאות (מושג, קיים, דבר, רצון ומקום).\u003c/p>\u003cp>הצעת קטע קישור בפתיחת הקטע: ובעומק הלשון יש להוסיף ולבאר את שורשי המושגים:\u003c/p>\u003cp>נוסח הקטע בשלימותו:\u003c/p>\u003cp>שורשי לשון הקודש בהגדרת המעשה, הרצון והמקום\u003c/p>\u003cp>א. שורשי נטל, נתן, הונחה ומנחה\u003c/p>\u003cp>מילת \"נטל\" הוא משורש \"טל\", דטל הוא דשמים; ו\"נטל\" כמו נפעל, שהחפץ הניטל נחשב טל דמי שהיה בידו לפנים. ואי עביד זה מי שהיתה בידו בעצמו היה נקרא \"מטיל\", דעביד דבר זה לטל. וכשאחר יקח הוי נטל, אבל זה רק במי שלא כיוון בהנחת החפץ במקום אלא רק לעזבו.\u003c/p>\u003cp>אבל אם כיוון שיגיע למקום מסוים לצורכו או לאדם אחר, אין נקרא מעשה שלו על שם עזיבת החפץ אלא על הגעתו: ולצורכו יקרא \"מניח\", ולאדם אחר יקרא \"נתן\".\u003c/p>\u003cp>והוא משורש \"תן\", שהאות ט' היא עזיבת דבר את דבר, והאות ת' היא החזקת דבר את דבר. ו\"טן\" היא פעולת העזיבה בדבר שממנו נעזב, ו\"תן\" היא פעולת ההחזקה בדבר שמחזיק; ו\"טל\" היא עזיבה לצורך, ו\"תל\" היא החזקה לצורך; ו\"נתן\" היא מי שעושה פעולת החזקה של אחר, ו\"תין\" הוא כוח החזקת דברים, ו\"תוּן\" הוא דבר שאפשר או שראוי לפעול בו החזקה, ו\"נתין\" הוא מי שכוח הפועל החזקת דברים שלו נפעל על ידי אחר, וה\"נתון\" הוא דבר שיכולת החזקתו נפעלה על ידי אחר, ו\"מתון\" הוא דבר [הערת עורך: המשפט נקטע במקור].\u003c/p>\u003cp>ב. שורשי רץ וצר --- רצון מול יצירה\u003c/p>\u003cp>וזה משמעות \"רץ\" ו\"צר\" שהם הפכים, כי הם שתי סיבות לשינוי מקום: אלא שהרץ הוא רץ מסיבת עצמו, והצר הוא צר לאחר; ו\"רצון\" יגדיר הדבר כשייך לרוצה ומעשה בו עצמו, ו\"יצירה\" תגדיר את היוצר כצר בדבר אחר.\u003c/p>\u003cp>והנקודה נקודה, והאורך שלושה נקודות כי לא יחשבו הזהים לדבר חדש אלא בשלושה; והרוחב שלושה אורכים כאמור, וכן העומק שלושה רוחבים; וגדר כולם באמצעיתם, כי אז יהיה הוא בכוח השניים. והאורך כוחו בהמשכיות, והרוחב בגודלו, והעומק במרחק, וכולם יחד בחלל.\u003c/p>\u003cp>ג. שורש קום, מקום ומנוס\u003c/p>\u003cp>וכבר ביארנו לשון \"מקום\", היינו, מה שיש בו קוּם; וקוֹם הוא שם כללי, וקיום הוא מעשה כמו סיום, כי אין המקום מעשה באיזה דבר אלא גדר בעצמו שיש בו יכולת קוּם, וכמו מנוס. וקוּם הוא בדבר כמו נוּס; וכשאומר \"מקומו\", היינו, שגדר המקום לעצמו וגדר הקיום דבר לעצמו, ורק יש ביניהם שייכות כי עתה קום הדבר הוא במקום זה.\u003c/p>\u003cp>ואמר \"אבד מנוס ממני\", כי אין מדובר במקום שהיה רגיל לנוס בו אלא מקום ששייך לנוס בו; אבל אמר \"משגבי ומנוסי\", כי שם נס תמיד, והיינו, ממנו נוס שלי, אבל מנוס אין זה שלו, וע\"כ אמר \"ממני\".\u003c/p>\u003cp>אבל לשון \"מקומי\", היינו, מקום המוכן לי, כמו לון ומלון, בשונה ממילת \"מלונה\" שביאורה מקום שלנו בו.\u003c/p>\u003cp>ד. דרשות הוצאה מיוחדות: בן סורר ומורה וראיית \"כה/זה\"\u003c/p>\u003cp>(הנה מצאנו שמיעטו בדין בן סורר אי אביו ואמו חירגים משום דכתיב \"והוציאו אותו\", והיינו, דמשמע ליה דהוא בהוצאה שנעשית על ידי יציאתם שלהם, שהם אוחזים אותו ויוצאים בעצמם והוא עמם, שהרי אין צורך להוצאה שעל ידי זריקה וכו' שיהיה המוציא עצמו יוצא עם המוצא; ונראה שזה נלמד מהא דכתיב \"והוציאו\" ולא \"ויוציאו\", שאין גדר מעשה שלהם במקום הבן אלא במקום שלהם, והיינו, שביתם ושער העיר הם מקומות שימוש שלהם, ואמרו \"והוציאו אותו\", היינו, מה שיש בזה משמעות לגבי מלאות מקומם, שעד עתה היה ביתם מלא מבנם ועתה הם מוציאים ויהיה ביתם ריק; וכיון שאמר זה בלשון הוציאו ולא גרשו, הרי שזה מעשה בשני המקומות, היינו, מרשות הבית לרשות שער העיר; אלא שלא אמר זקני עירם ושער מקומם אלא עירו ומקומו, וע\"כ לא יועיל מה שיזרקוהו שאין זה מעשה במה שהוא בשער מקומו אלא מקומם, ואין להם שייכות במקומו אלא על ידי מעשה במקום, וזה אינו אלא על ידי שיניחוהו שם, וכיון שכן זה אין שייך אלא במי שיש לו יכולת הילוך).\u003c/p>\u003cp>(ההבדל בין לשון \"כה\" ללשון \"זה\" הוא ש\"כה\" מתייחס לכלל הדברים ו\"זה\" מתייחס לדבר מסוים, וע\"כ נקרא חוסר יכולת זיהוי כהות העין, והיינו, שיש לו יכולת לראות כלל הדברים, וכמו ביצחק שראה שהגיע יעקב אבל לא יכל לזהות אם הוא יעקב או עשיו; והבחנת הזהות קרויה ראיה, והבחנה שאינה בעלת יכולת זיהוי אלא רק כלל הדברים קרויה פניה, כמו שאמר \"ויפן כה וכה וירא כי אין איש\", היינו, ראיה שיש בה לשלול היות דבר אך בהיותו אין זיהויו אפשרי, וכן הוא אומר \"אל תפנו אל האלילים\", היינו, שאין באלילים אפשרות זיהוי האלוקים, וע\"כ יהיו פונים אל אלילים רבים, וע\"כ הוא נקרא על שם פניית הראש).\u003c/p>\u003cp>(ממך יצא יועץ [נחום א, יא], והיינו, דבר שיש ממנו תוצאת דבר אחר, וזה לשון עצה שיש בה הוראת דרך לתוצאה הנרצית, וכמו עיבור וקידוש שמהם יצא דבר, היינו, איסור כרת התלוי בזמן).\u003c/p>\u003cp>הצעת קטע קישור בסיום הקטע: ולפי השורשים האלה יובן עומק ההגדרות שבמושגי המציאות.\u003c/p>"}, {"id": "59", "n": 7, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0076 | חומרה: בינונית | קטגוריה: הגדרה פילוסופית ובהירות מונחים. הגדרת „מושג” כ„מה שנתפס כדבר מוגדר ביחס לדבר אחר ודורש השגה ואינו מצוי” מערבת כמה שאלות: מה ניתן להמשיג, מה קיים במחשבה, ומה קיים במציאות. יש להבחין בין מושג שכלי, מושא המושג, והקיום הממשי של אותו מושא; דבר יכול להיות מושג אף שאינו קיים בפועל, ולכן המשפט „ודורש השגה ואינו מצוי” עלול להיקרא כאילו המושג עצמו אינו מצוי. כדאי להגדיר את המונחים „מושג מציאותי”, „מושג בלבד” ו„מציאותי” בנפרד ולשמור על שימוש אחיד בהמשך.\u003c/p>"}, {"id": "60", "n": 8, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0077 | חומרה: גבוהה | קטגוריה: הבחנה בין קיום מושגי לקיום ממשי. בפסקה זו „קיום” מתואר פעם כקיום של מושג בהשגת השכל ופעם כקיום במציאות, ובהמשך נקבע שקיום הוא בחינה מוחלטת וחיובית ואי־קיום שלילית. אלה שני מובנים שונים: אפשר לדבר על מושג אפשרי שאינו ממומש, ועל דבר שמתקיים בפועל; אין לערבב בין תקפותו/אפשרותו של מושג לבין מציאותו הממשית. גם הניסוח „ובחינת זו היא בחינה מוחלטת” דורש תיקון לשוני („ובחינה זו”). מומלץ להפריד בין „קיים כמושג” לבין „קיים במציאות” ולהשתמש בכל אחד מהם בעקביות.\u003c/p>"}, {"id": "61", "n": 9, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0078 | חומרה: בינונית | קטגוריה: הגדרה מעגלית של המציאות. ההגדרה „המציאות היא כל הדברים המצויים” קרובה להגדרה מעגלית, ובהמשך נאמר שאין למציאות משמעות מלבד עצם הקיום, אך מיד מיוחס לה תפקיד בהגדרת יחסים בין דברים. כדאי להבחין בין „מציאות” במשמעות הכוללת (כל מה שקיים), „מציאות של דבר” (מצבו/קיומו), ו„יחסים במציאות” (התאמה או סתירה בין דברים). ההבחנה תסייע למנוע שימוש במילה „מציאות” פעם כמכלול ופעם כמצב של פרט.\u003c/p>"}, {"id": "62", "n": 10, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0079 | חומרה: גבוהה | קטגוריה: הנחה אונטולוגית לא מבוססת. הניסוח „קיומו ללא שיהיה תלוי בקיום דבר אחר” ולאחריו „הדבר העצם ושאר המציאות כמקרה בעצם” מציג טענה אונטולוגית חזקה בדבר עצמאותם של חפץ ומקום. יש להבהיר אם „נפרד” פירושו שניתן לדון בכל אחד בנפרד לצורך הניתוח, או טענה על עצמאות ממשית של קיומו. בפרט, מקום וחפץ אינם בהכרח עצמים עצמאיים באותו מובן, והיחס ביניהם הוא חלק מרכזי מהמשך הדיון. אם זו הפרדה אנליטית בלבד, מומלץ לכתוב זאת במפורש ולא להשתמש במונחי „עצם” ו„מקרה” כאילו הוכחה כאן עמדה מטפיזית.\u003c/p>"}, {"id": "63", "n": 11, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0080 | חומרה: גבוהה | קטגוריה: שימוש לא אחיד במושג מציאות אחת. הטענה שכל הדברים הקיימים הם „מציאות אחת” מבחינת עצם הקיום, אך לאחר הגדרת דבר נפרד „תיפרד המציאות” ביחס אליו, נשענת על החלפת מובן של המילה „מציאות”: פעם היא מכלול כל הדברים, פעם יחידת קיום מופשטת, ופעם תחום נפרד של פרט. יש להגדיר אם מדובר בחלוקה מושגית של השכל או בחלוקה אונטולוגית של המציאות עצמה. גם הדוגמה של חפץ ומקום צריכה להבהיר מה נפרד ומה נשאר משותף: קיומם, צורתם, או היחס „חפץ מונח במקום”.\u003c/p>"}, {"id": "64", "n": 12, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0081 | חומרה: גבוהה | קטגוריה: הגדרת מקום ושימוש ברשות. הקביעה שאוויר אינו „מקום בר שימוש כשימוש נפרד” טעונה הבחנה בין אוויר שאינו חפץ שימושי לעצמו לבין אוויר הנכלל בתחום רשות הלכתית. באוויר רשות היחיד נאמר „אוויר רשות היחיד עולה עד לרקיע” (שבת ז ע״א), ובאוויר רשות הרבים יש דינים התלויים בגובה ובעשרה טפחים; לכן אין להוציא את האוויר מן הדיון במקום בלי להגדיר את סוג השימוש וההקשר. גם הדוגמה של דבר הגדול מבית סאתיים טעונה מקור והגדרה: בית סאתיים הוא שיעור בתחום דיני קרפף/היקף מחיצות, ולא קביעה שהשטח אינו ראוי לשימוש כלל. יש להבחין בין שימושיות פיזית, מעמד הלכתי של רשות, וכשרותה לטלטול.\u003c/p>"}, {"id": "65", "n": 13, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0082 | חומרה: גבוהה | קטגוריה: הגדרת חפץ, כלי ואוכל. כאן „כלי” מוגדר כ„שם חפץ המוכן לשימוש מסוים” ו„אוכל” כ„שימוש נפרד”, אך אלו קטגוריות הלכתיות שאינן בהכרח שלבים עוקבים באותו סולם. כלי יכול לשמש לכמה שימושים, ואוכל הוא מעמד של דבר הראוי לאכילה; ייתכן שחפץ הוא גם כלי וגם אוכל (כגון כלי הראוי לאכילה או מאכל המשמש לדבר אחר). יש להגדיר מה ההבדל בין „בר שימוש”, „כלי”, „אוכל” ו„רשות”, ולהביא מקור לגדר של „צורה שימושית”. אחרת מתקבל רושם שמדובר בהגדרות הלכתיות מוסכמות, בעוד שהן חלק מן המודל המושגי של המחבר.\u003c/p>"}, {"id": "66", "n": 14, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0083 | חומרה: קריטית | קטגוריה: דיוק בשיעורי הוצאה ורשויות. בפסקה אחת נכרכים כמה שיעורים שאינם מודדים אותו דבר: גרוגרת היא שיעור האוכל/החפץ להוצאת שבת; ארבעה על ארבעה טפחים הוא שיעור מקום חשוב במקומות הנצרכים לכך; שש עשרה אמה היא רוחב רשות הרבים לפי הגדר המקובל, לצד תנאים ודיונים נוספים (כגון מפולש ותנאי רשות הרבים לשיטות השונות). אין להציגם כשלושה „שיעורי שימוש” מקבילים. יש לציין את המקורות המדויקים: משנה שבת ז, ב ושבת עג ע״א לעניין שיעור הוצאה; שבת ו ע״א/שבת צט ע״ב ועירובין ו ע״א לעניין רשות הרבים ושיעוריה; ולהפריד בין שיעור החפץ, שיעור המקום ושיעור הרשות.\u003c/p>"}, {"id": "67", "n": 15, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0084 | חומרה: קריטית | קטגוריה: דיני קניין ושיתוף. הקביעה שאין שיתוף גמור בקניין הגוף, ושקניית חפץ משותפת אינה אלא „משמעות משותפת בערכו המסחרי”, אינה נכונה כפשוטה וטעונה תיקון. שותפים יכולים להיות בעלים משותפים בגוף החפץ עצמו, ולא רק בעלי אינטרס מסחרי משותף; דיני שותפים בבבא בתרא (פרק ראשון, ובפרט משנה א, א) מניחים בעלות משותפת ממשית בגוף הנכס. יש להבחין בין קניין הגוף, קניין פירות, זכות שימוש, וחלוקת זכויות בין שותפים; אין להפוך כל שיתוף בגוף לעניין של ערך מסחרי בלבד. כמו כן, יש להביא מקור להבחנה המוצעת בין קניין המונע תפיסת שימוש של אחרים לבין קניין בערך מסחרי.\u003c/p>"}, {"id": "68", "n": 16, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0085 | חומרה: קריטית | קטגוריה: יישום בדיני שכירות רשות מנכרי. היישום לדין שכירו ולקיטו דורש דיוק. בעירובין סד ע״א נלמד ששכירו ולקיטו של נכרי יכולים להשכיר את רשותו, ובשו״ע או״ח שפב, יא נפסק ששוכרים מאשתו או משכירו ולקיטו אף כשהנכרי מוחה; אולם אין זה נובע רק מכך שמי שקיבל רשות שימוש „שותף בקניין השימוש”. הפוסקים דנים בתנאי הרשות להשתמש בבית/בחצר, ובמצב שבו יוחד לשכיר חדר שאין לבעל הבית שימוש בו קיימת הבחנה (ראו שו״ע או״ח שפב, טו–יח ומשנה ברורה שם). יש להסביר אם כוח השכיר להשכיר הוא מדין ייצוג/מעמד שכירו ולקיטו, מזכות שימוש ממשית, או מדין אחר. בלי ההבחנה הזו הראיה אינה מוכיחה את המודל הקנייני שנבנה כאן.\u003c/p>"}, {"id": "69", "n": 17, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0086 | חומרה: גבוהה | קטגוריה: התאמת המודל לשיעורים ההלכתיים. בסיכום נכתב „כאוכל חשוב” ו„כמקום חשוב” לאחר שהוזכרו שיעור גרוגרת ושיעור ארבעה. יש להבהיר אם „אוכל חשוב” פירושו כמות של גרוגרת, או קטגוריית אוכל הראוי לאכילה; וכן אם „מקום חשוב” הוא מקום שיש בו ארבעה על ארבעה טפחים או מושג שימושי רחב יותר. שיעורי חיוב בהוצאה אינם בהכרח הגדרה של חשיבות החפץ או המקום בכל דיני שבת. יש להציג בנפרד את המעמד המושגי ואת השיעור ההלכתי, ולציין את מקורו של כל שיעור.\u003c/p>"}, {"id": "70", "n": 18, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0087 | חומרה: בינונית | קטגוריה: בהירות ומונחים. הפסקה מייחסת למקום ארבעה תפקידים שונים: מכיל חומר, מקיים אותו, מכין אותו לשימוש, ומשמש אותו; ובמקביל לחפץ תפקידים של תפיסת חלל, מקום שימוש ותפיסת רשות. יש כאן מערכת מושגים עשירה, אך לא ברור אם אלה תכונות פיזיות, יחסים שימושיים, או קביעות הלכתיות. מומלץ להציג טבלה קצרה של צמד המונחים בכל רובד (מציאותי, שימושי, הלכתי) ולתת דוגמה אחת לכל צמד; אחרת הקורא אינו יודע מתי „מקום” הוא חלל פיזי ומתי הוא רשות הלכתית.\u003c/p>"}, {"id": "843", "n": 19, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-046 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ואם נגדיר את משמעות חפץ במקום נגדיר בזה כמה משמעויות. מבחינת החפץ, מה שהוא צורת חומר, שהוא צורת דבר שאינו סותר...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>57 (המושג תוך מתייחס לאחידות המקום. שדבר שכל חלליו מוגדרים כדבר אחד, דבר הנמצא בחלק ממנו יוגדר כנמצא בתוכו. וביחס למציאות, היינו, דבר שיש לו גבולות ביחס לכל צדדיו, הרי שחללו יוגדר כאחד ביחס לגבולותיו)\u003c/p>"}, {"id": "844", "n": 20, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-047 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/הוצאה - רשויות - חצרות - תחומין - ממוספר.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ואם נגדיר את משמעות חפץ במקום נגדיר בזה כמה משמעויות. מבחינת החפץ, מה שהוא צורת חומר, שהוא צורת דבר שאינו סותר...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>(מושג תוך יתייחס לאחידות המקום. שדבר שכל חלליו מוגדרים כדבר אחד, דבר הנמצא בחלק ממנו יוגדר כנמצא בתוכו. וביחס למציאות, היינו, דבר שיש לו גבולות ביחס לכל צדדיו, הרי שחללו יוגדר כאחד ביחס לגבולותיו)\u003c/p>\u003cp>משמעות מציאות האמורה בדברים ומעשים\u003c/p>"}, {"id": "71", "n": 21, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0088 | חומרה: בינונית | קטגוריה: זהות הדבר לאורך שינוי. כאן נאמר שהמציאות עצמה אינה מגדירה שינוי, אך אפשר להגדיר דבר שמצבו השתנה כ„דבר אחד שהשתנה”. זהו מעבר חשוב שדורש קריטריון לזהות הדבר לאורך זמן: מה משמר את זהותו כאשר מצבו משתנה, ומהו שינוי שמפסיק את זהותו ויוצר דבר חדש? בהמשך הפרק ההבחנה בין חידוש מציאות לבין שינוי מצב תהיה יסוד להגדרת המלאכות; לכן כדאי להגדיר כבר כאן את התנאים שבהם אותו חפץ נשאר אותו חפץ, ולא להסתפק באמירה שהוא „מושג אחד”.\u003c/p>"}, {"id": "72", "n": 22, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0089 | חומרה: בינונית | קטגוריה: הגדרת מעשה ומונחי לוגיקה. ההגדרה „המעשה הוא הדבר הנושא את הנעשה” וההקבלה „המעשה הוא נשוא של העושה” משתמשות במונחי נושא/נשוא במשמעות לוגית־דקדוקית, אך לא ברור אם הכוונה היא לתחביר, ליחס אונטולוגי או ליחס הלכתי. גם האמירה שהמעשה מקשר בין העושה לנעשה דורשת דוגמה שתראה מהו המעשה כישות נפרדת מן העושה ומן התוצאה. מומלץ לקבוע מונח אחד לכל יחס ולהדגים במעשה הוצאה פשוט: אדם, חפץ, עקירה, העברה והנחה.\u003c/p>"}, {"id": "73", "n": 23, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0090 | חומרה: קריטית | קטגוריה: גדר גרימה במלאכות שבת. הטענה „כיון שבשבת אין גדר המעשה גרימת התוצאה” רחבה מאוד ואינה מתיישבת כפשוטה עם מלאכות רבות שהחיוב בהן כרוך ביצירת התוצאה – כגון זורע, אופה, כותב ומבעיר. ייתכן שהמחבר מבחין בין גרימת התוצאה כיסוד סיבתי לבין כוחו של אדם המייחס אליו את המעשה; אם כן, יש לנסח זאת במפורש. יש להבחין בין גרמא, כוחו, מעשה בידיים, מלאכה שאינה צריכה לגופה ומלאכת מחשבת, ולא לקבוע שכל מלאכות שבת אינן בגדר גרימת תוצאה בלי ביסוס.\u003c/p>"}, {"id": "74", "n": 24, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0092 | חומרה: גבוהה | קטגוריה: זרייה ורוח מסייעתו. הדוגמה של „זורה ורוח מסייעתו” אינה מקבילה בפשטות לשניים שעשאוה: מדובר באדם אחד הזורה כאשר הרוח מסייעת לו, ולא בשני בני אדם שכל אחד מהם מבצע חלק מן הפעולה. יש לברר אם הדוגמה באה להוכיח שכוח מסייע אינו מנתק את ייחוס המעשה לעושה, או שהיא משמשת ראיה לכך שכוח האדם אינו חייב להיות סיבה מספקת לתוצאה. יש לציין את מקור הסוגיה המדויק (בבא קמא ס ע״א; והשוו שבת עג ע״א בסוגיית זורה) ולנסח את ההבחנה בין סיוע טבעי לבין שיתוף של שני עושי מלאכה.\u003c/p>"}, {"id": "75", "n": 25, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0091 | חומרה: קריטית | קטגוריה: שניים שעשאוה והגדרת כוח העושה. ההסבר לדין „שניים שעשאוה” חייב להתייחס לחלוקה התלמודית המפורשת: זה יכול וזה יכול; זה אינו יכול וזה אינו יכול; וזה יכול וזה אינו יכול (שבת צב ע״ב–צג ע״א). אין די לומר שאחד עשה רק חלק מן המעשה, משום שבחלק מן המצבים שניים חייבים ובאחרים פטורים, לפי יכולת כל אחד ולפי חלוקת הכוחות. יש להביא את הסוגיה ולהגדיר מהו „בעל המעשה” לעומת „שותף בתוצאה”, ולציין אם ההסבר המוצע מחדש את גדר הסוגיה או רק מבאר אחד מדיניה.\u003c/p>"}, {"id": "76", "n": 26, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0093 | חומרה: בינונית | קטגוריה: סדר ההגדרות והבחנה בין לוגיקה למציאות. הפסקה קובעת שהמציאות קודמת להגדרת המעשה, גם כאשר לעיתים „משמעות המציאות ביחס למעשה” מתבררת רק לאחר הגדרת המעשה. יש להבהיר אם הקדימות היא אונטולוגית (המציאות קיימת קודם למעשה), מתודולוגית (כך נכון לסדר את הדיון), או לוגית (הגדרת המעשה מניחה מושגי מציאות). שלוש האפשרויות אינן זהות. מומלץ לנסח במפורש את סוג הקדימות, משום שהטענה תשמש בהמשך לבניית סדר המושגים.\u003c/p>"}, {"id": "77", "n": 27, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0094 | חומרה: גבוהה | קטגוריה: הבחנה בין מצב קיים למעשה. הדוגמה של דבר המונח בתוך כלי כמקרה שבו „הכלי עושה מעשה של הכלה” מערבת בין מצב סטטי (הכלי מכיל חפץ) לבין פעולה (הנחת החפץ בכלי). אם הכוונה היא למעשה ההנחה, יש לתאר את המעבר ממצב שבו החפץ מחוץ לכלי למצב שבו הוא בתוכו; אם הכוונה לעצם יחס ההכלה, אין הכרח שזה ייחשב „מעשה” במובן של פעולה שנעשתה. ההבחנה חשובה במיוחד בהמשך, שבו המחבר מבקש להגדיר מעשה גם ללא שינוי במציאות.\u003c/p>"}, {"id": "78", "n": 28, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0095 | חומרה: גבוהה | קטגוריה: הגדרת שינוי ורציפות. הניסוח שלפיו „אין הכוונה שתהיה מציאות של שינוי כי המציאות היא הנמצא” אינו ברור: שינוי הוא בדרך כלל תיאור של מעבר בין מצבים של אותו דבר, ולא בהכרח „מציאות נוספת” לצד הדבר המשתנה. יש להבחין בין המציאות הקודמת, המציאות המאוחרת, והיחס/התהליך המגדיר אותן כשינוי אחד. כדאי להגדיר האם „מעשה” הוא עצם המעבר, היחס הסיבתי בין המצבים, או הסיפור המאחד אותם; ההבחנה הזו חיונית להגדרת מלאכת הוצאה כמעשה שינוי מקום.\u003c/p>"}, {"id": "79", "n": 29, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0096 | חומרה: בינונית | קטגוריה: דוגמת שינוי מקום. הדוגמה של חפץ שעבר ממקום למקום מועילה, אך המשפט „לא נצטרך לומר שהיה המקום הקודם מקומו” דורש ביאור. מעבר ממקום למקום אינו שולל בהכרח שהמקום הקודם היה מקומו של החפץ; הוא רק מאפשר לתאר את שני המצבים כתהליך אחד. יש להבחין בין „מקומו” במובן הפיזי, מקום שבו החפץ מונח, לבין „מקומו” במובן ההלכתי (מקום שביתה, רשותו או מקום קניינו). בלי ההבחנה עלול הקורא לייחס למעבר הפיזי תוצאה קניינית או הלכתית.\u003c/p>"}, {"id": "80", "n": 30, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0097 | חומרה: גבוהה | קטגוריה: הכללה פילוסופית. הקביעה שסיבה ומסובב, תיקון וקלקול, חידוש ושינוי הם מושגים „שלא יתכנו בהגדרת מציאות” ויכולים להתקיים רק ביחס למעשה, רחבה מדי אם היא נאמרת על המציאות בכלל: יחסי סיבה ותוצאה קיימים גם בתהליכים טבעיים שאינם מעשה אנושי. נראה שהכוונה היא למושגים של ייחוס, אחריות ותכלית בתוך מעשה מיוחס לעושה. אם כך, יש לנסח שהמושגים הללו מקבלים משמעות הלכתית/ייחוסית ביחס למעשה, ולא לשלול את קיומם במציאות הטבעית.\u003c/p>"}, {"id": "81", "n": 31, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0098 | חומרה: גבוהה | קטגוריה: הגדרת מעשה כקירבה. הדוגמה של „מעשה קירבה” דורשת הבחנה בין עצם יחס הקירבה שבין שני דברים לבין פעולה שיצרה את הקירבה. אם אדם שלישי מקרב שני דברים, יש פעולה שלו ותוצאה של קירבה; אך אם שני דברים פשוט נמצאים קרובים, לא ברור מדוע זה „מעשה” ולא מצב מציאותי. גם כאשר אחד מן המתקרבים מקרב את עצמו לאחר, יש לברר אם המעשה מיוחס למקרב, למי שאליו מקרבים, או ליחס שביניהם. כדאי להציג דוגמה הלכתית ממשית שתבהיר את הנפקא מינה.\u003c/p>"}, {"id": "82", "n": 32, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0099 | חומרה: גבוהה | קטגוריה: הבחנה בין שני סוגי מעשה. החלוקה בין קירבה שהיא „מעשה של אחד המתקרבים” לבין קירבה שהיא יחס כולל של שני המתקרבים עדיין אינה חדה. יש להגדיר מהו הקריטריון המבחין: מי יזם את השינוי, באיזה גוף נעשתה הפעולה, או למי מיוחסת התוצאה? בדוגמת כלי וחצר, יש להבהיר אם ההנחה בתוך החצר היא מעשה של החפץ, של החצר, של האדם המניח, או של יחס המקום והחפץ. בלא קריטריון עקבי, שתי הקטגוריות עלולות לחפוף.\u003c/p>"}, {"id": "83", "n": 33, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0100 | חומרה: קריטית | קטגוריה: דיוק בסוגיית מתעסק בחלבים ועריות. הדוגמה של מי שנתן חלב לתוך פיו של אחר נסמכת על דין „המתעסק בחלבים ועריות חייב שכן נהנה” (כריתות יט ע״ב; וכן סנהדרין סב ע״ב). יש לדייק שהחיוב המיוחד נובע מן ההנאה באיסורי אכילה/ביאה, ולא בהכרח מכך שהנהנה „עשה מעשה” במובן הרגיל או שיצר את המציאות המחודשת. הסוגיה דנה במתעסק, ובשבת הפטור קשור ל„מלאכת מחשבת”; לכן יש להבחין בין הנאה, מעשה, כוונה וייחוס התוצאה לעושה. כמו כן, ההפניה לתוספות בסנהדרין סה טעונה דף/עמוד ודיבור המתחיל מדויקים, ולציין מה בדיוק הם חולקים: האם ההנאה נגרמת על ידי העושה או שהיא עצם מעשה הנהנה.\u003c/p>"}, {"id": "84", "n": 34, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0101 | חומרה: גבוהה | קטגוריה: הבחנה בין גרימה לתוצאה. כאן נאמר שהמעשה כולל לעיתים את גרימת המציאות המחודשת, כלומר שהמעשה צריך להיות סיבה לקיום התוצאה. יש להבחין בין גרימה ישירה, כוחו, גרמא, וסיוע של גורם טבעי; בלעדי הבחנה זו לא ברור מתי המעשה מיוחס לעושה ומתי הוא רק תנאי או גורם מסייע. מומלץ להגדיר את דרגת הסיבתיות הנדרשת ולהביא דוגמה מן ההלכה, בפרט משום שבדיני שבת יש הבדלים בין מעשה בידיים לגרמא.\u003c/p>"}, {"id": "85", "n": 35, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0102 | חומרה: בינונית | קטגוריה: הבחנה בין המצאה לגרימה. ההגדרה של „המצאת מציאות” – מצב שבו לפני המעשה לא הייתה המציאות הנעשית ולאחריו היא קיימת – קרובה מאוד להגדרת מעשה כגורם תוצאה שבפסקה הקודמת. יש להבהיר מהו ההבדל: האם „גרימה” מתייחסת לקשר הסיבתי בין העושה לתוצאה, ואילו „המצאה” מתייחסת לכך שהדבר עצמו לא היה קיים קודם? אם כן, יש להציג זאת בטבלה עם דוגמה; אחרת שתי הקטגוריות אינן נראות נפרדות.\u003c/p>"}, {"id": "86", "n": 36, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0103 | חומרה: גבוהה | קטגוריה: הבחנה בין חידוש מצב לשינוי. ההגדרה של מעשה המחדש מצב בדבר קיים נשענת על כך שזהות הדבר נשארת אחת לפני ואחרי, ורק מצב מסוים משתנה. יש להגדיר כיצד יודעים שזהו „אותו דבר” ומהו מצב חדש בעל חשיבות הלכתית, ולא שינוי מקרי שאינו נחשב מעשה. בפרט, הביטוי „גרימת מציאות מחודשת של הדבר עם המצב” מערב בין יצירת מצב לבין שינוי מצב, שהם שני המושגים שהפסקאות הבאות מבקשות להפריד. כדאי להוסיף דוגמה ברורה לכל צד.\u003c/p>"}, {"id": "87", "n": 37, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0104 | חומרה: גבוהה | קטגוריה: חפיפה בין שתי קטגוריות מעשה. ההבחנה בין „המצאת מצב בדבר קיים” (פסקה 235) לבין „שינוי מצב הדבר” (כאן) אינה מובנת עדיין. בשני המקרים נראה שמדובר באותו חפץ לפני ואחרי, ובשניהם חל שינוי במצבו. האם ההבדל הוא שמצב אחד נחשב תוצאה חדשה בעלת חשיבות עצמית, ואילו באחר החשיבות היא בעצם המעבר? אם כן, יש לנסח קריטריון חד ולהדגים אותו במלאכה אחת; אחרת שתי הקטגוריות חופפות ואינן מאפשרות סיווג דטרמיניסטי של מלאכות.\u003c/p>"}, {"id": "845", "n": 38, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-048 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/הקדמות וכללים - רשויות - הוצאה - עירובין - תחומין.docx / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"והנה מעשה אף שהוא הגדרה כללית של מקיים מציאות, גדר המעשה המסוים ישתנה בכל מקום לפי עניינו, ולכן הוא אינו תלוי ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>ממצא: פרק זה (שו' 6-145) הוא הפרק המפותח ביותר בכל ההקדמה - בניין פילוסופי-הגדרתי עצמאי ושלם (מושג/קיים/דבר/נפרד/בעל-צורה/בר-שימוש וכו', ולאחר מכן דעת/בקשה/מחשבה/רצון/כוונה) שאינו נצרך ליישום בסוגיה קונקרטית. עברתי בעיון על הפרקים המקבילים בחלק ב' (\"שנים שעשאוה\", \"מתעסק\", \"דבר שאין מתכוין\") ולא מצאתי בהם תוכן עצמאי חדש ברמת הכלליות המתאימה - רובם יישום (לעיתים במחלוקת אביי-רבא, ר\"א-ר\"י) של המסגרת שכבר בנויה כאן במלואה.\u003c/p>"}, {"id": "88", "n": 39, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-05", "h": "\u003cp>E-0105 | חומרה: בינונית | קטגוריה: יחס בין מעשה, פעולה ומספר פעולות. הטענה שגדר המעשה המסוים אינו תלוי באחידות הפעולה או בכמות הפעולות חשובה, אך דורשת דוגמאות הלכתיות והגבלות. במלאכות מסוימות רצף פעולות מצטרף למעשה אחד, ובאחרות כל פעולה יכולה להיחשב מעשה נפרד; גם הפסק, שינוי כוונה או תוצאה ביניים עשויים להשפיע על הצירוף. יש להבחין בין „מעשה” במובן המושגי, „פעולה” במובן הפיזי, ו„שיעור/צירוף” במובן ההלכתי, ולהסביר מתי מעשים אחרים הם חלק מהגדרת המעשה ומתי הם רק תנאי חיצוני.\u003c/p>"}, {"id": "846", "n": 40, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-049 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (4 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. מצוות שביתת מלאכה\u003c/p>\u003cp>2. מצוות ומלאכת שבת\u003c/p>\u003cp>3. והנה אחר שנתבארו גדרי מעשה הנוגעים למעשה ככלל (המציאות, המעשה, העושה), נבאר גדרי איסור מלאכת שבת בפרט, ומה שיש בגדרם כמעשה המסוים להשפיע על גדרים שנתבארו לעיל.\u003c/p>\u003cp>4. (3) - מצוות ומלאכת שבת\u003c/p>"}]};
